CREATE VIEW market.vw_broker_ksei_confirm AS WITH max_broker_dt AS (SELECT max(date) AS d FROM main.broker_activity), max_ksei_dt AS (SELECT max(Date) AS d FROM ksei.monthly_snapshot), max_price_dt AS (SELECT max(trading_date) AS d FROM market.daily_transactions), broker_latest AS (SELECT stock_code, round((sum(CASE  WHEN ((side = 'BUY')) THEN ("value") ELSE 0 END) / 1000000000.0), 3) AS broker_buy_miliar, round((sum(CASE  WHEN ((side = 'SELL')) THEN (abs("value")) ELSE 0 END) / 1000000000.0), 3) AS broker_sell_miliar, round((sum("value") / 1000000000.0), 3) AS broker_net_miliar, count(DISTINCT broker_code) AS broker_count FROM main.broker_activity WHERE (date = (SELECT d FROM max_broker_dt)) GROUP BY stock_code), ksei_smart_flow AS (SELECT Code AS stock_code, round((((Local_CP_Chg_Val + Local_PF_Chg_Val) + Local_IB_Chg_Val) / 1000000000.0), 3) AS local_smart_flow_miliar, round((((Foreign_CP_Chg_Val + Foreign_PF_Chg_Val) + Foreign_IB_Chg_Val) / 1000000000.0), 3) AS foreign_smart_flow_miliar, round(((((((Local_CP_Chg_Val + Local_PF_Chg_Val) + Local_IB_Chg_Val) + Foreign_CP_Chg_Val) + Foreign_PF_Chg_Val) + Foreign_IB_Chg_Val) / 1000000000.0), 3) AS total_smart_flow_miliar FROM ksei.monthly_snapshot WHERE (Date = (SELECT d FROM max_ksei_dt))), price AS (SELECT stock_code, "close", change_percent FROM market.daily_transactions WHERE (trading_date = (SELECT d FROM max_price_dt)))SELECT COALESCE(b.stock_code, k.stock_code, p.stock_code) AS stock_code, cp.sector, p."close", p.change_percent, COALESCE(b.broker_net_miliar, 0) AS broker_net_miliar, COALESCE(b.broker_count, 0) AS broker_count, COALESCE(k.local_smart_flow_miliar, 0) AS ksei_local_smart_flow_miliar, COALESCE(k.foreign_smart_flow_miliar, 0) AS ksei_foreign_smart_flow_miliar, COALESCE(k.total_smart_flow_miliar, 0) AS ksei_total_smart_flow_miliar, CASE  WHEN (((COALESCE(b.broker_net_miliar, 0) > 0) AND (COALESCE(k.total_smart_flow_miliar, 0) > 0))) THEN ('✅ CONFIRMED BUY') WHEN (((COALESCE(b.broker_net_miliar, 0) < 0) AND (COALESCE(k.total_smart_flow_miliar, 0) < 0))) THEN ('✅ CONFIRMED SELL') WHEN (((COALESCE(b.broker_net_miliar, 0) > 0) AND (k.stock_code IS NULL))) THEN ('🟡 BROKER ONLY') WHEN (((COALESCE(b.broker_net_miliar, 0) > 0) AND (COALESCE(k.total_smart_flow_miliar, 0) < 0))) THEN ('🔄 DIVERGENCE: Broker beli, KSEI distribusi') WHEN (((COALESCE(b.broker_net_miliar, 0) < 0) AND (COALESCE(k.total_smart_flow_miliar, 0) > 0))) THEN ('🔄 DIVERGENCE: KSEI akumulasi, Broker jual') ELSE '⚪ NO SIGNAL' END AS confirmation FROM broker_latest AS b FULL JOIN ksei_smart_flow AS k ON ((b.stock_code = k.stock_code)) FULL JOIN price AS p ON ((COALESCE(b.stock_code, k.stock_code) = p.stock_code)) LEFT JOIN market.company_profile AS cp ON ((COALESCE(b.stock_code, k.stock_code, p.stock_code) = cp.stock_code)) ORDER BY abs(COALESCE(b.broker_net_miliar, 0)) DESC;

