-- market.vw_c_broker_score
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_broker_score AS SELECT ba.stock_code, ba.accumulation_phase, ba.flow_regime, ba.smart_accumulated_30d_miliar, bc.foreign_convergence_level, bc.dual_category_convergence, bc.category_alignment, bc.foreign_buyers_5d, bc.inst_buyers_5d, CASE  WHEN ((ba.accumulation_phase = 'MATURE_ACCUMULATION')) THEN (8) WHEN ((ba.accumulation_phase = 'BUILDING_ACCUMULATION')) THEN (6) WHEN ((ba.accumulation_phase = 'EARLY_ACCUMULATION')) THEN (4) WHEN ((ba.accumulation_phase = 'FADING_ACCUMULATION')) THEN (1) WHEN ((ba.accumulation_phase = 'DISTRIBUTION')) THEN (0) ELSE 2 END AS phase_pts, CASE  WHEN ((ba.flow_regime = 'SMART_BUY_RETAIL_SELL')) THEN (7) WHEN ((ba.flow_regime = 'ALL_BUYING')) THEN (5) WHEN ((ba.flow_regime = 'MIXED')) THEN (2) WHEN ((ba.flow_regime = 'SMART_SELL_RETAIL_BUY')) THEN (0) WHEN ((ba.flow_regime = 'INSTITUTIONAL_EXIT')) THEN (0) ELSE 2 END AS regime_pts, CASE  WHEN ((bc.foreign_convergence_level = 'STRONG')) THEN (5) WHEN ((bc.foreign_convergence_level = 'MODERATE')) THEN (3) WHEN ((bc.foreign_convergence_level = 'WEAK')) THEN (1) ELSE 0 END AS convergence_pts, least(20, ((CASE  WHEN ((ba.accumulation_phase = 'MATURE_ACCUMULATION')) THEN (8) WHEN ((ba.accumulation_phase = 'BUILDING_ACCUMULATION')) THEN (6) WHEN ((ba.accumulation_phase = 'EARLY_ACCUMULATION')) THEN (4) WHEN ((ba.accumulation_phase = 'FADING_ACCUMULATION')) THEN (1) ELSE 2 END + CASE  WHEN ((ba.flow_regime = 'SMART_BUY_RETAIL_SELL')) THEN (7) WHEN ((ba.flow_regime = 'ALL_BUYING')) THEN (5) WHEN ((ba.flow_regime = 'MIXED')) THEN (2) ELSE 0 END) + CASE  WHEN ((bc.foreign_convergence_level = 'STRONG')) THEN (5) WHEN ((bc.foreign_convergence_level = 'MODERATE')) THEN (3) WHEN ((bc.foreign_convergence_level = 'WEAK')) THEN (1) ELSE 0 END)) AS broker_score FROM market.vw_s_broker_accumulation AS ba LEFT JOIN market.vw_s_broker_convergence AS bc ON ((ba.stock_code = bc.stock_code));

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_composite_score
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_composite_score AS WITH latest_date AS (SELECT max(trading_date) AS d FROM market.daily_transactions), latest_ksei AS (SELECT max(snapshot_date) AS d FROM ksei.vw_f_ksei_monthly_delta_v2), base AS (SELECT ph.stock_code, ph.sector, ph.group_name, ph."close", ph.change_percent, ph.return_5d, ph.return_20d, ph.high_52w, ph.low_52w, COALESCE(ph.vwma_20d, ph."close") AS vwma_20d, COALESCE(ph.aov_ratio_ma20, 1) AS aov_ratio_ma20, COALESCE(vp.clean_whale_signal, CAST('f' AS BOOLEAN)) AS clean_whale_signal FROM market.vw_f_price_history AS ph LEFT JOIN market.vw_f_volume_profile AS vp ON (((ph.stock_code = vp.stock_code) AND (ph.trading_date = vp.trading_date))) WHERE (ph.trading_date = (SELECT d FROM latest_date))), foreign_src AS (SELECT stock_code, foreign_is_buyer, foreign_buy_days_20d, COALESCE(net_foreign_5d_miliar, 0) AS fgn_5d_miliar, COALESCE(net_foreign_20d_miliar, 0) AS fgn_20d_miliar FROM market.vw_f_foreign_flow_daily WHERE (trading_date = (SELECT d FROM latest_date))), broker_src AS (SELECT stock_code, COALESCE(foreign_buy_brokers_5d, 0) AS fgn_buyers_5d, (COALESCE(foreign_net_5d, 0) / 1000000000.0) AS broker_fgn_5d_miliar, (COALESCE(inst_net_5d, 0) / 1000000000.0) AS inst_5d_miliar, (COALESCE(prime_net_5d, 0) / 1000000000.0) AS prime_5d_miliar FROM main.vw_f_broker_category_rolling), whale_src AS (SELECT stock_code, max(whale_quality_score) AS whale_quality, count_star() FILTER (WHERE (whale_verdict != 'NO_WHALE')) AS whale_days_20d, bool_or(clean_whale_signal) AS has_whale FROM market.vw_s_whale_timing WHERE (trading_date >= ((SELECT d FROM latest_date) - CAST('20 days' AS INTERVAL))) GROUP BY stock_code), ksei_src AS (SELECT stock_code, smart_money_miliar, Is_CorpAction_Suspect FROM ksei.vw_f_ksei_monthly_delta_v2 WHERE (snapshot_date = (SELECT d FROM latest_ksei))), insider_src AS (SELECT stock_code, conviction_tier, pengendali_buy_30d, buy_count_30d, buy_value_30d_miliar FROM main.vw_f_insider_rolling), all_scores AS (SELECT b.stock_code, b.sector, b.group_name, b."close", b.change_percent, b.return_5d, b.return_20d, least(25, greatest(0, (((CASE  WHEN ((COALESCE(f.fgn_20d_miliar, 0) > 100)) THEN (10) WHEN ((COALESCE(f.fgn_20d_miliar, 0) > 40)) THEN (8) WHEN ((COALESCE(f.fgn_20d_miliar, 0) > 10)) THEN (5) WHEN ((COALESCE(f.fgn_20d_miliar, 0) > 0)) THEN (3) ELSE 0 END + CASE  WHEN (((f.fgn_5d_miliar > 0) AND ((f.fgn_5d_miliar / 5.0) > (f.fgn_20d_miliar / 20.0)))) THEN (8) WHEN ((f.fgn_5d_miliar > 0)) THEN (5) ELSE 0 END) + CASE  WHEN (b.clean_whale_signal) THEN (5) ELSE 0 END) + CASE  WHEN ((b.aov_ratio_ma20 > 1.5)) THEN (2) ELSE 0 END))) AS foreign_score, least(20, greatest(0, ((CASE  WHEN ((COALESCE(br.fgn_buyers_5d, 0) >= 4)) THEN (8) WHEN ((COALESCE(br.fgn_buyers_5d, 0) >= 2)) THEN (5) WHEN ((COALESCE(br.fgn_buyers_5d, 0) >= 1)) THEN (3) ELSE 0 END + CASE  WHEN ((COALESCE(br.inst_5d_miliar, 0) > 50)) THEN (7) WHEN ((COALESCE(br.inst_5d_miliar, 0) > 10)) THEN (5) WHEN ((COALESCE(br.inst_5d_miliar, 0) > 0)) THEN (2) ELSE 0 END) + CASE  WHEN ((COALESCE(br.prime_5d_miliar, 0) > 20)) THEN (5) WHEN ((COALESCE(br.prime_5d_miliar, 0) > 5)) THEN (3) WHEN ((COALESCE(br.prime_5d_miliar, 0) > 0)) THEN (1) ELSE 0 END))) AS broker_score, least(15, greatest(0, ((COALESCE(w.whale_days_20d, 0) * 2) + CASE  WHEN ((COALESCE(w.whale_quality, 0) >= 7)) THEN (5) WHEN (w.has_whale) THEN (3) ELSE 0 END))) AS whale_score, least(10, greatest(0, ((CASE  WHEN (((b.return_20d > 10) AND (b.return_5d > 0))) THEN (4) WHEN (((b.return_20d > 5) AND (b.return_5d > 0))) THEN (3) WHEN ((b.return_20d > 0)) THEN (2) ELSE 0 END + CASE  WHEN ((b.return_5d > (b.return_20d / 4.0))) THEN (3) ELSE 0 END) + CASE  WHEN ((b."close" > (b.vwma_20d * 1.02))) THEN (3) WHEN ((b."close" > b.vwma_20d)) THEN (1) ELSE 0 END))) AS price_score, CASE  WHEN (k.Is_CorpAction_Suspect) THEN (0) WHEN ((COALESCE(k.smart_money_miliar, 0) > 100)) THEN (20) WHEN ((COALESCE(k.smart_money_miliar, 0) > 20)) THEN (14) WHEN ((COALESCE(k.smart_money_miliar, 0) > 5)) THEN (8) WHEN ((COALESCE(k.smart_money_miliar, 0) > 0)) THEN (4) ELSE 0 END AS ksei_score, COALESCE(k.Is_CorpAction_Suspect, CAST('f' AS BOOLEAN)) AS ksei_suspect, CASE  WHEN (((i.conviction_tier = 'HIGH') AND (i.pengendali_buy_30d > 0))) THEN (10) WHEN ((i.conviction_tier = 'HIGH')) THEN (8) WHEN ((i.conviction_tier = 'MEDIUM')) THEN (5) WHEN ((i.buy_count_30d > 0)) THEN (3) ELSE 0 END AS insider_score FROM base AS b LEFT JOIN foreign_src AS f ON ((b.stock_code = f.stock_code)) LEFT JOIN broker_src AS br ON ((b.stock_code = br.stock_code)) LEFT JOIN whale_src AS w ON ((b.stock_code = w.stock_code)) LEFT JOIN ksei_src AS k ON ((b.stock_code = k.stock_code)) LEFT JOIN insider_src AS i ON ((b.stock_code = i.stock_code)))SELECT stock_code, sector, group_name, "close", change_percent, return_5d, return_20d, foreign_score, broker_score, whale_score, price_score, ksei_score, insider_score, ksei_suspect AS ksei_redistributed, CASE  WHEN (ksei_suspect) THEN (least(100, ((((least(25, (foreign_score + 6)) + least(20, (broker_score + 5))) + least(15, (whale_score + 4))) + least(10, (price_score + 3))) + least(10, (insider_score + 2))))) ELSE least(100, (((((foreign_score + broker_score) + whale_score) + price_score) + ksei_score) + insider_score)) END AS composite_score, (((foreign_score + broker_score) + whale_score) + price_score) AS daily_trigger_score, (ksei_score + insider_score) AS monthly_confirm_score, CASE  WHEN ((CASE  WHEN (ksei_suspect) THEN (least(100, ((((least(25, (foreign_score + 6)) + least(20, (broker_score + 5))) + least(15, (whale_score + 4))) + least(10, (price_score + 3))) + least(10, (insider_score + 2))))) ELSE least(100, (((((foreign_score + broker_score) + whale_score) + price_score) + ksei_score) + insider_score)) END >= 80)) THEN ('STRONG_BUY') WHEN ((CASE  WHEN (ksei_suspect) THEN (least(100, ((((least(25, (foreign_score + 6)) + least(20, (broker_score + 5))) + least(15, (whale_score + 4))) + least(10, (price_score + 3))) + least(10, (insider_score + 2))))) ELSE least(100, (((((foreign_score + broker_score) + whale_score) + price_score) + ksei_score) + insider_score)) END >= 65)) THEN ('BUY') WHEN ((CASE  WHEN (ksei_suspect) THEN (least(100, ((((least(25, (foreign_score + 6)) + least(20, (broker_score + 5))) + least(15, (whale_score + 4))) + least(10, (price_score + 3))) + least(10, (insider_score + 2))))) ELSE least(100, (((((foreign_score + broker_score) + whale_score) + price_score) + ksei_score) + insider_score)) END >= 50)) THEN ('ACCUMULATE') WHEN ((CASE  WHEN (ksei_suspect) THEN (least(100, ((((least(25, (foreign_score + 6)) + least(20, (broker_score + 5))) + least(15, (whale_score + 4))) + least(10, (price_score + 3))) + least(10, (insider_score + 2))))) ELSE least(100, (((((foreign_score + broker_score) + whale_score) + price_score) + ksei_score) + insider_score)) END >= 35)) THEN ('WATCH') WHEN ((CASE  WHEN (ksei_suspect) THEN (least(100, ((((least(25, (foreign_score + 6)) + least(20, (broker_score + 5))) + least(15, (whale_score + 4))) + least(10, (price_score + 3))) + least(10, (insider_score + 2))))) ELSE least(100, (((((foreign_score + broker_score) + whale_score) + price_score) + ksei_score) + insider_score)) END >= 20)) THEN ('NEUTRAL') ELSE 'AVOID' END AS composite_tier FROM all_scores;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_composite_tier_pct
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_composite_tier_pct AS SELECT cs.stock_code, cs.composite_score, cs.composite_tier AS tier_absolute, CASE  WHEN ((cs.composite_score >= c.p99)) THEN ('STRONG_BUY') WHEN ((cs.composite_score >= c.p95)) THEN ('BUY') WHEN ((cs.composite_score >= c.p85)) THEN ('ACCUMULATE') WHEN ((cs.composite_score >= c.p50)) THEN ('WATCH') ELSE 'NEUTRAL' END AS tier_pct FROM market.vw_c_composite_score AS cs CROSS JOIN (SELECT * FROM market.tb_score_calibration WHERE (metric = 'composite_score')) AS c;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_conviction_screener
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_conviction_screener AS SELECT rank_overall AS conviction_rank, stock_code, composite_score, composite_tier, daily_trigger_score, monthly_confirm_score, CASE  WHEN (((monthly_confirm_score >= 10) AND (daily_trigger_score >= 45))) THEN ('TRIPLE_CONFIRM') WHEN (((monthly_confirm_score >= 5) AND (daily_trigger_score >= 35))) THEN ('DUAL_CONFIRM') ELSE 'DAILY_ONLY' END AS conviction_reason, foreign_score, broker_score, whale_score, ksei_score, insider_score, ksei_redistributed, sector, group_name, "close", return_5d, return_20d FROM market.vw_c_top_accumulation WHERE (composite_tier IN ('STRONG_BUY', 'BUY', 'ACCUMULATE')) ORDER BY conviction_rank;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_daily_screener
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_daily_screener AS SELECT cs.stock_code, cs.daily_trigger_score, cs.foreign_score, cs.broker_score, cs.whale_score, cs.price_score, cs.composite_score, cs.composite_tier, cs.foreign_flow_direction, cs.broker_phase, cs.stealth_quality, cs.stealth_lens_count, cs.price_regime, cs.broker_regime, COALESCE(cp.sector, 'Others') AS sector, ph."close", ph.change_percent, ph.return_5d, ph.return_20d, ph.volume, ph."value", rank() OVER (ORDER BY cs.daily_trigger_score DESC) AS daily_rank FROM market.vw_c_composite_score AS cs LEFT JOIN market.company_profile AS cp ON ((cs.stock_code = cp.stock_code)) LEFT JOIN market.vw_f_price_history AS ph ON (((cs.stock_code = ph.stock_code) AND (ph.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) WHERE (cs.daily_trigger_score >= 20) ORDER BY cs.daily_trigger_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_distribution_warning
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_distribution_warning AS SELECT bd.stock_code, bd.distribution_intensity, bd.distribution_stage, bd.foreign_exit_signal, bd.inst_exit_signal, bd.foreign_net_5d, bd.foreign_net_20d, bd.retail_net_5d, cs.composite_score, cs.broker_score, cs.foreign_score, COALESCE(cp.sector, 'Others') AS sector, ph."close", ph.return_5d, ph.return_20d, ph.change_percent FROM market.vw_s_broker_distribution AS bd INNER JOIN market.vw_c_composite_score AS cs ON ((bd.stock_code = cs.stock_code)) LEFT JOIN market.company_profile AS cp ON ((bd.stock_code = cp.stock_code)) LEFT JOIN market.vw_f_price_history AS ph ON (((bd.stock_code = ph.stock_code) AND (ph.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) WHERE (bd.distribution_intensity IN ('HIGH', 'MEDIUM')) ORDER BY cs.composite_score ASC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_foreign_rotation
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_foreign_rotation AS SELECT fsr.sector, fsr.foreign_today, fsr.foreign_5d, fsr.foreign_20d, fsr.rotation_signal, fsr.rank_today, sc.avg_composite_score, sc.avg_daily_score, sc.stock_count, sc.top_stock, sc.sector_tier, sl.leadership_status, sl.vs_market, sl.avg_change_pct FROM market.vw_s_foreign_sector_rotation AS fsr LEFT JOIN market.vw_c_sector_composite AS sc ON ((fsr.sector = sc.sector)) LEFT JOIN market.vw_s_sector_leadership AS sl ON (((fsr.sector = sl.sector) AND (sl.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) ORDER BY fsr.rank_today;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_foreign_score
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_foreign_score AS WITH latest AS (SELECT max(trading_date) AS d FROM market.daily_transactions), base AS (SELECT fa.stock_code, fa.net_foreign_5d_miliar, fa.net_foreign_20d_miliar, fa.foreign_buy_days_20d, fa.accumulation_intensity, fa.flow_direction, fa.is_reversal_buy, fd.divergence_type, fd.is_stealth_quality, pb.prime_net_5d, pb.prime_is_buyer_5d, pb.prime_conviction FROM market.vw_s_foreign_accumulation AS fa INNER JOIN market.vw_f_foreign_flow_daily AS ff ON (((fa.stock_code = ff.stock_code) AND (fa.trading_date = ff.trading_date))) LEFT JOIN market.vw_s_foreign_divergence AS fd ON (((fa.stock_code = fd.stock_code) AND (fa.trading_date = fd.trading_date))) LEFT JOIN market.vw_s_prime_broker_flow AS pb ON ((fa.stock_code = pb.stock_code)) WHERE (fa.trading_date = (SELECT d FROM latest)))SELECT stock_code, net_foreign_5d_miliar, net_foreign_20d_miliar, foreign_buy_days_20d, accumulation_intensity, flow_direction, divergence_type, is_stealth_quality, prime_conviction, CASE  WHEN ((flow_direction = 'CONSISTENT_INFLOW')) THEN (10) WHEN ((flow_direction = 'BUILDING_INFLOW')) THEN (8) WHEN ((flow_direction = 'NEW_INFLOW')) THEN (5) WHEN ((flow_direction = 'MIXED')) THEN (2) WHEN ((flow_direction = 'NEW_OUTFLOW')) THEN (0) ELSE 0 END AS flow_pts, least(8, round(((CAST(foreign_buy_days_20d AS DOUBLE) / 20.0) * 8))) AS buy_days_pts, CASE  WHEN ((divergence_type = 'STEALTH_ACCUMULATION')) THEN (5) WHEN ((divergence_type = 'BUYING_THE_DIP')) THEN (4) WHEN ((divergence_type = 'CONFIRMED_UPTREND')) THEN (3) WHEN ((divergence_type = 'NEUTRAL')) THEN (1) ELSE 0 END AS divergence_pts, CASE  WHEN ((prime_conviction = 'HIGH')) THEN (2) WHEN ((prime_conviction = 'MEDIUM')) THEN (1) ELSE 0 END AS prime_pts, least(25, (((CASE  WHEN ((flow_direction = 'CONSISTENT_INFLOW')) THEN (10) WHEN ((flow_direction = 'BUILDING_INFLOW')) THEN (8) WHEN ((flow_direction = 'NEW_INFLOW')) THEN (5) WHEN ((flow_direction = 'MIXED')) THEN (2) ELSE 0 END + least(8, round(((CAST(foreign_buy_days_20d AS DOUBLE) / 20.0) * 8)))) + CASE  WHEN ((divergence_type = 'STEALTH_ACCUMULATION')) THEN (5) WHEN ((divergence_type = 'BUYING_THE_DIP')) THEN (4) WHEN ((divergence_type = 'CONFIRMED_UPTREND')) THEN (3) WHEN ((divergence_type = 'NEUTRAL')) THEN (1) ELSE 0 END) + CASE  WHEN ((prime_conviction = 'HIGH')) THEN (2) WHEN ((prime_conviction = 'MEDIUM')) THEN (1) ELSE 0 END)) AS foreign_score FROM base;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_group_composite
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_group_composite AS SELECT cp.group_name, count(DISTINCT cs.stock_code) AS stock_count, round(avg(cs.composite_score), 1) AS avg_composite_score, round(avg(cs.daily_trigger_score), 1) AS avg_daily_score, count_star() FILTER (WHERE (cs.composite_tier IN ('STRONG_BUY', 'BUY'))) AS buy_count, "first"(cs.stock_code ORDER BY cs.composite_score DESC) AS top_stock, max(cs.composite_score) AS max_score, string_agg(((cs.stock_code || ':') || CAST(round(cs.composite_score) AS VARCHAR)), ', ' ORDER BY cs.composite_score DESC) AS stocks_with_scores, CASE  WHEN ((avg(cs.composite_score) >= 65)) THEN ('LEADING') WHEN ((avg(cs.composite_score) >= 50)) THEN ('ABOVE_AVG') WHEN ((avg(cs.composite_score) >= 35)) THEN ('AVERAGE') ELSE 'LAGGING' END AS group_tier FROM market.vw_c_composite_score AS cs INNER JOIN market.company_profile AS cp ON ((cs.stock_code = cp.stock_code)) WHERE (cp.group_name != 'Others') GROUP BY cp.group_name;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_insider_watchlist
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_insider_watchlist AS SELECT ins.stock_code, ins.conviction_tier, ins.direction_30d, ins.buy_count_30d, ins.sell_count_30d, ins.pengendali_buy_30d, ins.hc_buy_30d, ins.is_cluster_buy, ins.has_insider_buy_7d, ins.insider_direction_score, ins.last_tx_date, cs.composite_score, cs.composite_tier, cs.daily_trigger_score, cs.ksei_score, COALESCE(cp.sector, 'Others') AS sector, ph."close", ph.return_20d FROM main.vw_s_insider_buying AS ins INNER JOIN market.vw_c_composite_score AS cs ON ((ins.stock_code = cs.stock_code)) LEFT JOIN market.company_profile AS cp ON ((ins.stock_code = cp.stock_code)) LEFT JOIN market.vw_f_price_history AS ph ON (((ins.stock_code = ph.stock_code) AND (ph.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) WHERE (ins.buy_count_30d > 0) ORDER BY ins.insider_direction_score DESC, cs.composite_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_ksei_screener
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_ksei_screener AS SELECT cs.stock_code, cs.monthly_confirm_score, cs.ksei_score, cs.insider_score, cs.composite_score, ks.sm_entry_type, ks.signal_quality, ks.sm_trend, ks.sm_2m_positive, ks.sm_3m_positive, ks.smart_money_miliar, ks.sm_3m_cumulative_miliar, ks.smart_retail_divergence, ks.data_suspect, COALESCE(cp.sector, 'Others') AS sector, ph."close", ph.return_20d, rank() OVER (ORDER BY cs.ksei_score DESC) AS ksei_rank FROM market.vw_c_composite_score AS cs INNER JOIN ksei.vw_c_ksei_score AS ks ON ((cs.stock_code = ks.stock_code)) LEFT JOIN market.company_profile AS cp ON ((cs.stock_code = cp.stock_code)) LEFT JOIN market.vw_f_price_history AS ph ON (((cs.stock_code = ph.stock_code) AND (ph.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) WHERE ((ks.ksei_score >= 5) AND (NOT ks.data_suspect)) ORDER BY cs.ksei_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_market_summary
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_market_summary AS WITH latest_regime AS (SELECT * FROM market.vw_s_market_breadth_signal ORDER BY trading_date DESC LIMIT 1), score_dist AS (SELECT count_star() FILTER (WHERE (composite_tier = 'STRONG_BUY')) AS strong_buy_count, count_star() FILTER (WHERE (composite_tier = 'BUY')) AS buy_count, count_star() FILTER (WHERE (composite_tier = 'ACCUMULATE')) AS accumulate_count, count_star() FILTER (WHERE (composite_tier = 'WATCH')) AS watch_count, count_star() FILTER (WHERE (composite_tier = 'NEUTRAL')) AS neutral_count, count_star() FILTER (WHERE (composite_tier = 'AVOID')) AS avoid_count, round(avg(composite_score), 1) AS avg_market_score, round(avg(daily_trigger_score), 1) AS avg_daily_score, count_star() AS total_stocks FROM market.vw_c_composite_score)SELECT sd.*, lr.trading_date AS latest_trading_date, lr.market_regime, lr.foreign_stance, lr.breadth_score, lr.market_timing_signal, lr.is_accumulation_day, lr.is_risk_off_day, lr.total_value_triliun, lr.foreign_today AS net_foreign_today_miliar, lr.whale_count AS whale_events_today FROM score_dist AS sd CROSS JOIN latest_regime AS lr;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_price_score
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_price_score AS WITH latest AS (SELECT max(trading_date) AS d FROM market.daily_transactions)SELECT pm.stock_code, pm.price_regime, pm.momentum_direction, pm.return_5d, pm.return_20d, pm.near_52w_high, pm.dip_in_uptrend, bt.breakout_proximity, bt.breakout_readiness_score, bt.is_consolidating, pv.vwma_signal, pv.vwma_streak, CASE  WHEN ((pm.price_regime = 'STRONG_UPTREND')) THEN (4) WHEN ((pm.price_regime = 'UPTREND')) THEN (3) WHEN ((pm.price_regime = 'SIDEWAYS')) THEN (2) WHEN ((pm.price_regime = 'DOWNTREND')) THEN (0) ELSE 1 END AS regime_pts, CASE  WHEN ((pm.momentum_direction = 'ACCELERATING')) THEN (3) WHEN ((pm.momentum_direction = 'BUILDING')) THEN (2) WHEN ((pm.momentum_direction = 'STABLE')) THEN (1) WHEN ((pm.momentum_direction = 'FADING')) THEN (0) ELSE 0 END AS momentum_pts, CASE  WHEN ((bt.breakout_proximity = 'IMMINENT')) THEN (2) WHEN ((bt.breakout_proximity = 'NEAR')) THEN (1) ELSE 0 END AS breakout_pts, CASE  WHEN ((pv.vwma_signal IN ('STRONG_ABOVE', 'ABOVE'))) THEN (1) ELSE 0 END AS vwma_pts, least(10, (((CASE  WHEN ((pm.price_regime = 'STRONG_UPTREND')) THEN (4) WHEN ((pm.price_regime = 'UPTREND')) THEN (3) WHEN ((pm.price_regime = 'SIDEWAYS')) THEN (2) ELSE 0 END + CASE  WHEN ((pm.momentum_direction = 'ACCELERATING')) THEN (3) WHEN ((pm.momentum_direction = 'BUILDING')) THEN (2) WHEN ((pm.momentum_direction = 'STABLE')) THEN (1) ELSE 0 END) + CASE  WHEN ((bt.breakout_proximity = 'IMMINENT')) THEN (2) WHEN ((bt.breakout_proximity = 'NEAR')) THEN (1) ELSE 0 END) + CASE  WHEN ((pv.vwma_signal IN ('STRONG_ABOVE', 'ABOVE'))) THEN (1) ELSE 0 END)) AS price_score FROM market.vw_s_price_momentum AS pm LEFT JOIN market.vw_s_breakout_technical AS bt ON ((pm.stock_code = bt.stock_code)) LEFT JOIN market.vw_s_price_vs_vwma AS pv ON (((pm.stock_code = pv.stock_code) AND (pm.trading_date = pv.trading_date))) WHERE (pm.trading_date = (SELECT d FROM latest));

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_sector_composite
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_sector_composite AS SELECT COALESCE(cp.sector, 'Others') AS sector, count(DISTINCT cs.stock_code) AS stock_count, round(avg(cs.composite_score), 1) AS avg_composite_score, round(avg(cs.daily_trigger_score), 1) AS avg_daily_score, round(avg(cs.monthly_confirm_score), 1) AS avg_monthly_score, count_star() FILTER (WHERE (cs.composite_tier IN ('STRONG_BUY', 'BUY'))) AS buy_count, count_star() FILTER (WHERE (cs.composite_tier = 'AVOID')) AS avoid_count, "first"(cs.stock_code ORDER BY cs.composite_score DESC) AS top_stock, max(cs.composite_score) AS max_score, CASE  WHEN ((avg(cs.composite_score) >= 65)) THEN ('LEADING') WHEN ((avg(cs.composite_score) >= 50)) THEN ('ABOVE_AVG') WHEN ((avg(cs.composite_score) >= 35)) THEN ('AVERAGE') ELSE 'LAGGING' END AS sector_tier FROM market.vw_c_composite_score AS cs LEFT JOIN market.company_profile AS cp ON ((cs.stock_code = cp.stock_code)) GROUP BY COALESCE(cp.sector, 'Others');

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_stealth_ranked
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_stealth_ranked AS SELECT sa.stock_code, sa.lens_count, sa.stealth_score, sa.stealth_quality, sa.stealth_type, sa.sustained_foreign_20d_miliar, sa.sustained_buy_days_20d, sa.ksei_smart_miliar, sa.price_20d, sa.price_5d, cs.composite_score, cs.composite_tier, cs.daily_trigger_score, cs.foreign_score, cs.broker_score, cs.sector, cs.group_name, cs."close", cs.change_percent, row_number() OVER (ORDER BY sa.stealth_score DESC) AS stealth_rank FROM market.vw_s_stealth_accumulation AS sa LEFT JOIN market.vw_c_composite_score AS cs ON ((sa.stock_code = cs.stock_code)) WHERE (sa.stealth_score > 0) ORDER BY sa.stealth_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_top_accumulation
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_top_accumulation AS SELECT row_number() OVER (ORDER BY composite_score DESC) AS rank_overall, stock_code, composite_score, composite_tier, daily_trigger_score, monthly_confirm_score, foreign_score, broker_score, whale_score, price_score, ksei_score, insider_score, ksei_redistributed, sector, group_name, "close", change_percent, return_5d, return_20d, row_number() OVER (PARTITION BY sector ORDER BY composite_score DESC) AS rank_in_sector, row_number() OVER (ORDER BY daily_trigger_score DESC) AS rank_daily FROM market.vw_c_composite_score;

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_whale_score
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_whale_score AS WITH latest AS (SELECT max(trading_date) AS d FROM market.daily_transactions), whale_agg AS (SELECT stock_code, stealth_score, stealth_quality, stealth_type, lens_count, intraday_stealth_days, sustained_foreign_20d_miliar, sustained_buy_days_20d, lens_a_active, lens_b_active FROM market.vw_s_stealth_accumulation), whale_timing AS (SELECT stock_code, max(whale_quality_score) AS max_whale_quality, max(CASE  WHEN ((whale_verdict = 'FOREIGN_STEALTH_CONFIRMED')) THEN (1) ELSE 0 END) AS has_foreign_stealth, max(CASE  WHEN ((whale_verdict = 'PRIME_INSTITUTIONAL')) THEN (1) ELSE 0 END) AS has_prime_inst, sum(CASE  WHEN ((trading_date >= ((SELECT d FROM latest) - CAST('4 days' AS INTERVAL)))) THEN (1) ELSE 0 END) AS whale_events_5d, sum(CASE  WHEN ((trading_date >= ((SELECT d FROM latest) - CAST('19 days' AS INTERVAL)))) THEN (1) ELSE 0 END) AS whale_events_20d FROM market.vw_s_whale_timing GROUP BY stock_code)SELECT COALESCE(wa.stock_code, wt.stock_code) AS stock_code, COALESCE(wa.stealth_quality, 'NONE') AS stealth_quality, COALESCE(wa.stealth_score, 0) AS stealth_score, COALESCE(wa.lens_count, 0) AS lens_count, COALESCE(wt.max_whale_quality, 0) AS max_whale_quality, COALESCE(wt.whale_events_5d, 0) AS whale_events_5d, COALESCE(wt.whale_events_20d, 0) AS whale_events_20d, (COALESCE(wt.has_foreign_stealth, 0) = 1) AS has_foreign_stealth, (COALESCE(wt.has_prime_inst, 0) = 1) AS has_prime_inst, CASE  WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'CONFIRMED_TRIPLE')) THEN (6) WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'HIGH')) THEN (5) WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'STRONG')) THEN (4) WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'MODERATE')) THEN (2) WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'WATCH')) THEN (1) ELSE 0 END AS stealth_pts, least(6, (((COALESCE(wt.whale_events_5d, 0) * 2) + (COALESCE(wt.has_foreign_stealth, 0) * 2)) + (COALESCE(wt.has_prime_inst, 0) * 2))) AS timing_pts, least(3, COALESCE(wa.lens_count, 0)) AS lens_pts, least(15, ((CASE  WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'CONFIRMED_TRIPLE')) THEN (6) WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'HIGH')) THEN (5) WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'STRONG')) THEN (4) WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'MODERATE')) THEN (2) WHEN ((COALESCE(wa.stealth_quality, 'NONE') = 'WATCH')) THEN (1) ELSE 0 END + least(6, (((COALESCE(wt.whale_events_5d, 0) * 2) + (COALESCE(wt.has_foreign_stealth, 0) * 2)) + (COALESCE(wt.has_prime_inst, 0) * 2)))) + least(3, COALESCE(wa.lens_count, 0)))) AS whale_score FROM whale_agg AS wa FULL JOIN whale_timing AS wt ON ((wa.stock_code = wt.stock_code));

-- ─────────────────────────────────────────────────────────────
-- market.vw_c_whale_watchlist
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_c_whale_watchlist AS WITH latest AS (SELECT max(trading_date) AS d FROM market.daily_transactions)SELECT wt.stock_code, wt.trading_date, wt.whale_verdict, wt.whale_quality_score, wt.aov_tier, wt.stealth_flag, wt.net_foreign_miliar, wt.aov_ratio_ma20, wt."close", wt.change_percent, cs.composite_score, cs.composite_tier, cs.whale_score, cs.foreign_score, COALESCE(cp.sector, 'Others') AS sector FROM market.vw_s_whale_timing AS wt INNER JOIN market.vw_c_composite_score AS cs ON ((wt.stock_code = cs.stock_code)) LEFT JOIN market.company_profile AS cp ON ((wt.stock_code = cp.stock_code)) WHERE ((wt.trading_date >= ((SELECT d FROM latest) - CAST('4 days' AS INTERVAL))) AND (wt.whale_verdict IN ('FOREIGN_STEALTH_CONFIRMED', 'PRIME_INSTITUTIONAL', 'STEALTH_ACCUMULATION'))) ORDER BY wt.whale_quality_score DESC, wt.trading_date DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_breadth_history
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_breadth_history AS SELECT mb.trading_date, mb.total_stocks, mb.gainers, mb.losers, mb.unchanged, mb.adv_decline_ratio, mb.breadth_score, round(mb.total_value_triliun, 2) AS total_value_triliun, round(mb.net_foreign_miliar, 0) AS net_foreign_miliar, mb.foreign_stance, mb.whale_count, mb.anomaly_count, mb.avg_change_pct, mbs.market_regime, mbs.breadth_5d, mbs.breadth_20d, mbs.foreign_5d_total, mbs.regime_changed_today, mbs.market_timing_signal FROM market.vw_f_market_breadth AS mb LEFT JOIN market.vw_s_market_breadth_signal AS mbs ON ((mb.trading_date = mbs.trading_date)) ORDER BY mb.trading_date DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_broker_intel_tab
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_broker_intel_tab AS SELECT ba.stock_code, cs.composite_score, cs.composite_tier, cs.broker_score, ba.accumulation_phase, ba.flow_regime, ba.smart_accumulated_30d_miliar, cr.foreign_net_1d, cr.foreign_net_5d, cr.foreign_net_20d, cr.foreign_net_30d, cr.inst_net_1d, cr.inst_net_5d, cr.inst_net_20d, cr.inst_net_30d, cr.retail_net_5d, cr.retail_net_20d, cr.prime_net_5d, cr.prime_net_20d, cr.foreign_trend_5d_vs_20d, pb.prime_net_1d, pb.prime_net_5d, pb.prime_net_20d, pb.prime_buyers_5d, pb.prime_brokers_active, pb.prime_lead_signal, pb.prime_conviction, pb.prime_is_buyer_5d, pb.prime_is_buyer_20d, bc.foreign_buyers_5d, bc.foreign_sellers_5d, bc.inst_buyers_5d, bc.foreign_convergence_level, bc.dual_category_convergence, bc.category_alignment, bd.distribution_intensity, bd.distribution_stage, bd.foreign_exit_signal, COALESCE(cp.sector, 'Others') AS sector, COALESCE(cp.group_name, 'Others') AS group_name, ph."close", ph.change_percent, ph.return_20d FROM market.vw_s_broker_accumulation AS ba LEFT JOIN market.vw_c_composite_score AS cs ON ((ba.stock_code = cs.stock_code)) LEFT JOIN main.vw_f_broker_category_rolling AS cr ON ((ba.stock_code = cr.stock_code)) LEFT JOIN market.vw_s_prime_broker_flow AS pb ON ((ba.stock_code = pb.stock_code)) LEFT JOIN market.vw_s_broker_convergence AS bc ON ((ba.stock_code = bc.stock_code)) LEFT JOIN market.vw_s_broker_distribution AS bd ON ((ba.stock_code = bd.stock_code)) LEFT JOIN market.company_profile AS cp ON ((ba.stock_code = cp.stock_code)) LEFT JOIN market.vw_f_price_history AS ph ON (((ba.stock_code = ph.stock_code) AND (ph.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) ORDER BY cs.composite_score DESC NULLS LAST;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_composite_tab
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_composite_tab AS SELECT rank_overall, stock_code, composite_score, composite_tier, daily_trigger_score, monthly_confirm_score, foreign_score, broker_score, whale_score, price_score, ksei_score, insider_score, ksei_redistributed, round(((foreign_score / 25.0) * 100)) AS foreign_bar, round(((broker_score / 20.0) * 100)) AS broker_bar, round(((whale_score / 15.0) * 100)) AS whale_bar, round(((price_score / 10.0) * 100)) AS price_bar, round(((ksei_score / 20.0) * 100)) AS ksei_bar, round(((insider_score / 10.0) * 100)) AS insider_bar, sector, group_name, "close", change_percent, return_5d, return_20d, rank_in_sector, rank_daily FROM market.vw_c_top_accumulation;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_daily_flow_tab
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_daily_flow_tab AS WITH latest AS (SELECT max(trading_date) AS d FROM market.daily_transactions)SELECT ds.daily_rank, ds.stock_code, ds.daily_trigger_score, ds.composite_score, ds.composite_tier, ds.foreign_score, ds.broker_score, ds.whale_score, ds.price_score, ds.sector, ds."close", ds.change_percent, ds.return_5d, ds.return_20d, ds.volume, ds."value", COALESCE(ff.net_foreign_5d_miliar, 0) AS net_foreign_5d_miliar, COALESCE(ff.net_foreign_20d_miliar, 0) AS net_foreign_20d_miliar, ff.foreign_buy_days_20d, ff.stealth_day_flag, vp.vol_ratio_ma20, vp.vol_tier, vp.aov_ratio_ma20, vp.aov_tier, vp.clean_whale_signal, vp.stealth_flag, vp.lot_per_tx, (SELECT d FROM latest) AS trading_date FROM (SELECT cs.stock_code, cs.daily_trigger_score, cs.foreign_score, cs.broker_score, cs.whale_score, cs.price_score, cs.composite_score, cs.composite_tier, cp.sector, ph."close", ph.change_percent, ph.return_5d, ph.return_20d, ph.volume, ph."value", rank() OVER (ORDER BY cs.daily_trigger_score DESC) AS daily_rank FROM market.vw_c_composite_score AS cs LEFT JOIN market.company_profile AS cp ON ((cs.stock_code = cp.stock_code)) LEFT JOIN market.vw_f_price_history AS ph ON (((cs.stock_code = ph.stock_code) AND (ph.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) WHERE (cs.daily_trigger_score >= 20)) AS ds LEFT JOIN market.vw_f_foreign_flow_daily AS ff ON (((ds.stock_code = ff.stock_code) AND (ff.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) LEFT JOIN market.vw_f_volume_profile AS vp ON (((ds.stock_code = vp.stock_code) AND (vp.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) ORDER BY ds.daily_rank;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_deepdive_broker
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_deepdive_broker AS SELECT bcd.date, bcd.stock_code, bcd.foreign_net_miliar, bcd.local_inst_net_miliar, bcd.local_retail_net_miliar, bcd.prime_foreign_net_miliar, bcd.non_prime_foreign_net_miliar, bcd.foreign_buy_brokers, bcd.foreign_sell_brokers, bcd.inst_buy_brokers, bcd.retail_buy_brokers, bcd.total_net_miliar, bcd.flow_regime FROM main.vw_f_broker_category_daily AS bcd ORDER BY bcd.stock_code, bcd.date;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_deepdive_price
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_deepdive_price AS SELECT ph.stock_code, ph.trading_date, ph.open_price, ph.high, ph.low, ph."close", ph.change_percent, ph.volume, ph."value", ph.frequency, ph.vwma_20d, ph.ma20_volume, ph.return_1d, ph.return_5d, ph.return_20d, ph.return_60d, ph.high_52w, ph.low_52w, ph.pct_from_52w_high, ph.pct_from_52w_low, ph.sector, ph.group_name, vp.vol_ratio_ma20, vp.vol_tier, vp.aov_ratio_ma20, vp.aov_tier, vp.clean_whale_signal, vp.stealth_flag, vp.distribution_flag, vp.lot_per_tx, vp.avg_order_volume, round((ff.net_foreign_value / 1000000000.0), 3) AS net_foreign_daily_miliar, ff.net_foreign_5d_miliar, ff.net_foreign_20d_miliar, ff.foreign_buy_days_20d, ff.stealth_day_flag FROM market.vw_f_price_history AS ph LEFT JOIN market.vw_f_volume_profile AS vp ON (((ph.stock_code = vp.stock_code) AND (ph.trading_date = vp.trading_date))) LEFT JOIN market.vw_f_foreign_flow_daily AS ff ON (((ph.stock_code = ff.stock_code) AND (ph.trading_date = ff.trading_date))) ORDER BY ph.stock_code, ph.trading_date;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_deepdive_summary
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_deepdive_summary AS SELECT cs.stock_code, cs.composite_score, cs.composite_tier, cs.daily_trigger_score, cs.monthly_confirm_score, cs.foreign_score, cs.broker_score, cs.whale_score, cs.price_score, cs.ksei_score, cs.insider_score, cs.ksei_redistributed, cr.stealth_quality, sa.stealth_type, cs.sector, cs.group_name, cs."close", cs.change_percent, cs.return_5d, cs.return_20d, ph.return_60d FROM market.vw_c_composite_score AS cs LEFT JOIN market.vw_c_stealth_ranked AS cr ON ((cs.stock_code = cr.stock_code)) LEFT JOIN market.vw_s_stealth_accumulation AS sa ON ((cs.stock_code = sa.stock_code)) LEFT JOIN market.vw_f_price_history AS ph ON (((cs.stock_code = ph.stock_code) AND (ph.trading_date = (SELECT max(trading_date) FROM market.daily_transactions))));

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_distribution_feed
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_distribution_feed AS SELECT cs.stock_code, CASE  WHEN ((br.foreign_net_5d < -50000000000.0)) THEN ('HIGH') WHEN ((br.foreign_net_5d < -10000000000.0)) THEN ('MEDIUM') ELSE 'LOW' END AS distribution_intensity, CASE  WHEN (((br.foreign_net_20d < 0) AND (br.foreign_net_5d < 0))) THEN ('ACTIVE') WHEN ((br.foreign_net_5d < 0)) THEN ('STARTING') ELSE 'WATCH' END AS distribution_stage, (COALESCE(br.foreign_net_5d, 0) / 1000000000.0) AS foreign_exit_miliar, (COALESCE(br.inst_net_5d, 0) / 1000000000.0) AS inst_exit_miliar, cs.composite_score, cs.foreign_score, cs.broker_score, cs.sector, cs.group_name, cs."close", cs.change_percent, cs.return_5d, cs.return_20d FROM market.vw_c_composite_score AS cs LEFT JOIN main.vw_f_broker_category_rolling AS br ON ((cs.stock_code = br.stock_code)) WHERE (COALESCE(br.foreign_net_5d, 0) < 0);

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_foreign_flow_history
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_foreign_flow_history AS SELECT ff.stock_code, ff.trading_date, round((ff.net_foreign_value / 1000000000.0), 3) AS net_foreign_daily_miliar, ff.net_foreign_5d_miliar, ff.net_foreign_20d_miliar, ff.net_foreign_60d_miliar, round((ff.net_foreign_cumulative / 1000000000.0), 2) AS net_foreign_cumulative_miliar, ff.foreign_is_buyer, ff.foreign_buy_days_20d, ff.stealth_day_flag, ff.change_percent, ff.volume, ff."value" FROM market.vw_f_foreign_flow_daily AS ff ORDER BY ff.stock_code, ff.trading_date;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_group_momentum_tab
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_group_momentum_tab AS SELECT gc.group_name, gc.stock_count, gc.avg_composite_score, gc.avg_daily_score, gc.buy_count, gc.top_stock, gc.max_score, gc.stocks_with_scores, gc.group_tier, gm.avg_change_pct AS today_avg_chg, gm.vs_market AS today_vs_market, gm.net_foreign_miliar AS today_net_foreign, gm.foreign_net_5d, gm.whale_count AS today_whale_count, gm.momentum_state, gm.rotation_signal, gm.leader_stock, gm.laggard_stock, gm.momentum_score FROM market.vw_c_group_composite AS gc LEFT JOIN market.vw_s_group_momentum AS gm ON (((gc.group_name = gm.group_name) AND (gm.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) ORDER BY gc.avg_composite_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_market_pulse_tab
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_market_pulse_tab AS SELECT ms.latest_trading_date, ms.market_regime, ms.foreign_stance, ms.breadth_score, ms.market_timing_signal, ms.is_accumulation_day, ms.is_risk_off_day, ms.total_value_triliun, ms.net_foreign_today_miliar, ms.whale_events_today, ms.avg_market_score, ms.avg_daily_score, ms.total_stocks, ms.strong_buy_count, ms.buy_count, ms.accumulate_count, ms.watch_count, ms.neutral_count, ms.avoid_count, mr.breadth_5d, mr.breadth_20d, mr.foreign_5d_total, mr.foreign_20d_total, mr.return_5d_avg, mr.return_20d_avg, mr.regime_changed_today FROM market.vw_c_market_summary AS ms LEFT JOIN market.vw_s_market_regime AS mr ON ((ms.latest_trading_date = mr.trading_date));

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_screener_tab
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_screener_tab AS (SELECT 'DAILY' AS screener_type, daily_rank AS rank, stock_code, daily_trigger_score AS primary_score, composite_score, composite_tier, foreign_flow_direction AS signal_1, broker_phase AS signal_2, stealth_quality AS signal_3, sector, "close", change_percent, return_5d, return_20d FROM market.vw_c_daily_screener WHERE (daily_trigger_score >= 35)) UNION ALL (((SELECT 'KSEI' AS screener_type, ksei_rank AS rank, stock_code, ksei_score AS primary_score, composite_score, CASE  WHEN ((composite_score >= 80)) THEN ('STRONG_BUY') WHEN ((composite_score >= 65)) THEN ('BUY') WHEN ((composite_score >= 50)) THEN ('ACCUMULATE') WHEN ((composite_score >= 35)) THEN ('WATCH') WHEN ((composite_score >= 20)) THEN ('NEUTRAL') ELSE 'AVOID' END AS composite_tier, sm_entry_type AS signal_1, sm_trend AS signal_2, smart_retail_divergence AS signal_3, sector, "close", CAST(NULL AS DOUBLE) AS change_percent, CAST(NULL AS DOUBLE) AS return_5d, return_20d FROM market.vw_c_ksei_screener WHERE (ksei_score >= 10)) UNION ALL (SELECT 'CONVICTION' AS screener_type, conviction_rank AS rank, stock_code, composite_score AS primary_score, composite_score, composite_tier, conviction_reason AS signal_1, stealth_quality AS signal_2, ksei_sm_trend AS signal_3, sector, "close", CAST(NULL AS DOUBLE) AS change_percent, return_5d, return_20d FROM market.vw_c_conviction_screener)) UNION ALL (SELECT 'STEALTH' AS screener_type, stealth_rank AS rank, stock_code, stealth_score AS primary_score, composite_score, composite_tier, stealth_quality AS signal_1, stealth_type AS signal_2, CAST(NULL AS VARCHAR) AS signal_3, sector, "close", change_percent, CAST(NULL AS DOUBLE) AS return_5d, price_20d AS return_20d FROM market.vw_c_stealth_ranked WHERE (stealth_quality IN ('CONFIRMED_TRIPLE', 'HIGH', 'STRONG', 'MODERATE'))));

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_sector_rotation_tab
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_sector_rotation_tab AS SELECT fr.rank_today, fr.sector, fr.foreign_today, fr.foreign_5d, fr.foreign_20d, fr.rotation_signal, fr.avg_composite_score, fr.avg_daily_score, fr.stock_count, fr.top_stock, fr.sector_tier, fr.leadership_status, fr.vs_market, fr.avg_change_pct, round(COALESCE(fr.avg_composite_score, 0)) AS sector_score_display FROM market.vw_c_foreign_rotation AS fr ORDER BY fr.rank_today;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_top_broker_net
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_top_broker_net AS SELECT br.stock_code, br.broker_code, br.broker_name, br.category, br.origin, br.is_prime, br.is_prime_foreign, br.net_1d, br.net_5d, br.net_10d, br.net_20d, br.net_30d, br.net_lot_20d, br.buy_30d, br.sell_30d, br.is_buyer_1d, br.is_buyer_5d, br.is_buyer_30d, rank() OVER (PARTITION BY br.stock_code ORDER BY br.net_20d DESC) AS rank_buyer_20d, rank() OVER (PARTITION BY br.stock_code ORDER BY br.net_20d ASC) AS rank_seller_20d, CASE  WHEN ((br.net_20d > 0)) THEN ('NET_BUY') WHEN ((br.net_20d < 0)) THEN ('NET_SELL') ELSE 'NEUTRAL' END AS direction_20d FROM main.vw_f_broker_net_rolling AS br;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_watchlist_context
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_watchlist_context AS SELECT ta.stock_code, ta.composite_score, ta.composite_tier, ta.rank_overall, ta.daily_trigger_score, ta.monthly_confirm_score, ta.foreign_flow_direction, ta.broker_phase, ta.stealth_quality, ta.price_regime, ta.ksei_sm_trend, ta.insider_conviction, ta."close", ta.change_percent, ta.return_5d, ta.return_20d, ta.sector, ta.group_name, ta.free_float, vp.clean_whale_signal AS alert_whale_today, vp.stealth_flag AS alert_stealth_today, vp.distribution_flag AS alert_distribution_today, ff.stealth_day_flag AS alert_foreign_stealth_today, (ta.rank_overall - ta.rank_daily_only) AS rank_vs_daily_delta, (SELECT max(trading_date) FROM market.daily_transactions) AS data_as_of FROM market.vw_d_composite_tab AS ta LEFT JOIN market.vw_f_volume_profile AS vp ON (((ta.stock_code = vp.stock_code) AND (vp.trading_date = (SELECT max(trading_date) FROM market.daily_transactions)))) LEFT JOIN market.vw_f_foreign_flow_daily AS ff ON (((ta.stock_code = ff.stock_code) AND (ff.trading_date = (SELECT max(trading_date) FROM market.daily_transactions))));

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_whale_feed
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_whale_feed AS SELECT ww.trading_date, ww.stock_code, ww.whale_verdict, ww.whale_quality_score, ww.aov_tier, ww.stealth_flag, round(ww.net_foreign_miliar, 2) AS net_foreign_miliar, ww.aov_ratio_ma20, ww."close", ww.change_percent, ww.composite_score, ww.composite_tier, ww.whale_score, ww.sector, COALESCE(cp.group_name, 'Others') AS group_name FROM market.vw_c_whale_watchlist AS ww LEFT JOIN market.company_profile AS cp ON ((ww.stock_code = cp.stock_code)) ORDER BY ww.trading_date DESC, ww.whale_quality_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_d_whale_feed_new
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_d_whale_feed_new AS SELECT wf.stock_code, wf.trading_date, wf.whale_verdict, wf.whale_quality_score, wf.aov_ratio_ma20, wf.stealth_flag, wf.net_foreign_miliar, cs.composite_score, cs.composite_tier, cs.sector, cs.group_name, cs."close", cs.change_percent FROM market.vw_d_whale_feed AS wf LEFT JOIN market.vw_c_composite_score AS cs ON ((wf.stock_code = cs.stock_code)) ORDER BY wf.whale_quality_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_f_foreign_flow_daily
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_f_foreign_flow_daily AS SELECT stock_code, trading_date, foreign_buy_value, foreign_sell_value, net_foreign_value, sum(net_foreign_value) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS net_foreign_5d, sum(net_foreign_value) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS net_foreign_20d, sum(net_foreign_value) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS net_foreign_60d, round((sum(net_foreign_value) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) / 1000000000.0), 3) AS net_foreign_5d_miliar, round((sum(net_foreign_value) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) / 1000000000.0), 3) AS net_foreign_20d_miliar, round((sum(net_foreign_value) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) / 1000000000.0), 3) AS net_foreign_60d_miliar, sum(net_foreign_value) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS net_foreign_cumulative, (net_foreign_value > 0) AS foreign_is_buyer, sum(CASE  WHEN ((net_foreign_value > 0)) THEN (1) ELSE 0 END) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS foreign_buy_days_20d, ((net_foreign_value > 0) AND (change_percent <= 1.0)) AS stealth_day_flag, change_percent, volume, "value" FROM market.daily_transactions;

-- ─────────────────────────────────────────────────────────────
-- market.vw_f_group_daily
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_f_group_daily AS SELECT d.trading_date, cp.group_name, count(DISTINCT d.stock_code) AS stock_count, round(avg(d.change_percent), 3) AS avg_change_pct, count_star() FILTER (WHERE (d.change_percent > 0)) AS gainers, count_star() FILTER (WHERE (d.change_percent < 0)) AS losers, round((sum(d."value") / 1000000000.0), 2) AS total_value_miliar, round((sum(d.volume) / 1000000.0), 2) AS total_volume_mio_lot, round((sum(d.net_foreign_value) / 1000000000.0), 3) AS net_foreign_miliar, count_star() FILTER (WHERE d.whale_signal) AS whale_count, count_star() FILTER (WHERE d.big_player_anomaly) AS anomaly_count, count_star() FILTER (WHERE (d.aov_ratio_ma20 >= 1.5)) AS aov_spike_count, count_star() FILTER (WHERE (d."close" >= d.vwma_20d)) AS above_vwma_count, "first"(d.stock_code ORDER BY d.change_percent DESC) AS leader_stock, "first"(d.stock_code ORDER BY d.change_percent ASC) AS laggard_stock, "first"(d.stock_code ORDER BY d."value" DESC) AS most_active_stock, string_agg(d.stock_code, ', ' ORDER BY d."value" DESC) AS stocks_list, least(100, greatest(0, ((((CASE  WHEN ((avg(d.change_percent) > 0)) THEN (25) ELSE -10 END + CASE  WHEN ((sum(d.net_foreign_value) > 0)) THEN (25) ELSE -10 END) + CASE  WHEN ((count_star() FILTER (WHERE d.whale_signal) > 0)) THEN (20) ELSE 0 END) + CASE  WHEN ((count_star() FILTER (WHERE (d.change_percent > 0)) > count_star() FILTER (WHERE (d.change_percent < 0)))) THEN (15) ELSE 0 END) + CASE  WHEN ((avg(d.aov_ratio_ma20) >= 1.5)) THEN (15) ELSE 0 END))) AS momentum_score FROM market.daily_transactions AS d INNER JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)) WHERE (cp.group_name != 'Others') GROUP BY d.trading_date, cp.group_name;

-- ─────────────────────────────────────────────────────────────
-- market.vw_f_market_breadth
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_f_market_breadth AS SELECT trading_date, count(DISTINCT stock_code) AS total_stocks, count_star() FILTER (WHERE (change_percent > 0)) AS gainers, count_star() FILTER (WHERE (change_percent < 0)) AS losers, count_star() FILTER (WHERE (change_percent = 0)) AS unchanged, sum(volume) FILTER (WHERE (change_percent > 0)) AS up_volume, sum(volume) FILTER (WHERE (change_percent < 0)) AS down_volume, round((CAST(count_star() FILTER (WHERE (change_percent > 0)) AS DOUBLE) / "nullif"(count_star() FILTER (WHERE (change_percent < 0)), 0)), 3) AS adv_decline_ratio, round((sum("value") / 1000000000000.0), 3) AS total_value_triliun, round((sum(net_foreign_value) / 1000000000.0), 2) AS net_foreign_miliar, CASE  WHEN ((sum(net_foreign_value) > 50000000000.0)) THEN ('STRONG_INFLOW') WHEN ((sum(net_foreign_value) > 5000000000.0)) THEN ('INFLOW') WHEN ((sum(net_foreign_value) < -50000000000.0)) THEN ('STRONG_OUTFLOW') WHEN ((sum(net_foreign_value) < -5000000000.0)) THEN ('OUTFLOW') ELSE 'NEUTRAL' END AS foreign_stance, count_star() FILTER (WHERE whale_signal) AS whale_count, count_star() FILTER (WHERE big_player_anomaly) AS anomaly_count, round(avg(change_percent), 3) AS avg_change_pct, least(100, greatest(0, ((((CASE  WHEN ((count_star() FILTER (WHERE (change_percent > 0)) > count_star() FILTER (WHERE (change_percent < 0)))) THEN (30) ELSE 0 END + CASE  WHEN ((sum(net_foreign_value) > 0)) THEN (25) ELSE 0 END) + CASE  WHEN ((sum(volume) FILTER (WHERE (change_percent > 0)) > sum(volume) FILTER (WHERE (change_percent < 0)))) THEN (20) ELSE 0 END) + CASE  WHEN ((count_star() FILTER (WHERE whale_signal) >= 5)) THEN (15) WHEN ((count_star() FILTER (WHERE whale_signal) >= 1)) THEN (8) ELSE 0 END) + CASE  WHEN ((avg(change_percent) > 0)) THEN (10) ELSE 0 END))) AS breadth_score FROM market.daily_transactions GROUP BY trading_date;

-- ─────────────────────────────────────────────────────────────
-- market.vw_f_price_history
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_f_price_history AS WITH base AS (SELECT d.stock_code, d.trading_date, d.open_price, d.high, d.low, d."close", d.previous, d.change_percent, d.volume, d."value", d.frequency, d.vwma_20d, d.ma20_volume, d.avg_order_volume, d.aov_ratio_ma20, d.whale_signal, d.big_player_anomaly, d.tradeable_shares, COALESCE(cp.sector, 'Others') AS sector, COALESCE(cp.group_name, 'Others') AS group_name, COALESCE(cp.free_float, 0) AS free_float FROM market.daily_transactions AS d LEFT JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)))SELECT stock_code, trading_date, open_price, high, low, "close", previous, change_percent, volume, "value", frequency, vwma_20d, ma20_volume, avg_order_volume, aov_ratio_ma20, whale_signal, big_player_anomaly, tradeable_shares, sector, group_name, free_float, round(((("close" - lag("close", 1) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW)) / "nullif"(lag("close", 1) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW), 0)) * 100), 2) AS return_1d, round(((("close" - lag("close", 5) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW)) / "nullif"(lag("close", 5) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW), 0)) * 100), 2) AS return_5d, round(((("close" - lag("close", 20) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW)) / "nullif"(lag("close", 20) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW), 0)) * 100), 2) AS return_20d, round(((("close" - lag("close", 60) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW)) / "nullif"(lag("close", 60) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW), 0)) * 100), 2) AS return_60d, max(high) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW) AS high_52w, min(low) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW) AS low_52w, round(((("close" - max(high) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW)) / "nullif"(max(high) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW), 0)) * 100), 2) AS pct_from_52w_high, round(((("close" - min(low) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW)) / "nullif"(min(low) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN 251 PRECEDING AND CURRENT ROW), 0)) * 100), 2) AS pct_from_52w_low FROM base;

-- ─────────────────────────────────────────────────────────────
-- market.vw_f_sector_daily
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_f_sector_daily AS SELECT d.trading_date, COALESCE(cp.sector, 'Others') AS sector, count(DISTINCT d.stock_code) AS stock_count, round(avg(d.change_percent), 3) AS avg_change_pct, count_star() FILTER (WHERE (d.change_percent > 0)) AS gainers, count_star() FILTER (WHERE (d.change_percent < 0)) AS losers, round((sum(d."value") / 1000000000.0), 2) AS total_value_miliar, round((sum(d.volume) / 1000000.0), 2) AS total_volume_mio_lot, round((sum(d.net_foreign_value) / 1000000000.0), 3) AS net_foreign_miliar, round((sum(d.foreign_buy_value) / 1000000000.0), 3) AS foreign_buy_miliar, round((sum(d.foreign_sell_value) / 1000000000.0), 3) AS foreign_sell_miliar, count_star() FILTER (WHERE d.whale_signal) AS whale_count, count_star() FILTER (WHERE d.big_player_anomaly) AS anomaly_count, count_star() FILTER (WHERE (d.aov_ratio_ma20 >= 1.5)) AS aov_spike_count, count_star() FILTER (WHERE (d."close" >= d.vwma_20d)) AS above_vwma_count, "first"(d.stock_code ORDER BY d."value" DESC) AS top_stock_by_value, CASE  WHEN ((sum(d.net_foreign_value) > 50000000000.0)) THEN ('STRONG_INFLOW') WHEN ((sum(d.net_foreign_value) > 5000000000.0)) THEN ('INFLOW') WHEN ((sum(d.net_foreign_value) < -50000000000.0)) THEN ('STRONG_OUTFLOW') WHEN ((sum(d.net_foreign_value) < -5000000000.0)) THEN ('OUTFLOW') ELSE 'NEUTRAL' END AS foreign_direction, least(100, greatest(0, ((((((CASE  WHEN ((avg(d.change_percent) > 0)) THEN (20) ELSE -10 END + CASE  WHEN ((sum(d.net_foreign_value) > 0)) THEN (20) ELSE -10 END) + CASE  WHEN ((count_star() FILTER (WHERE (d.aov_ratio_ma20 >= 1.5)) > (count(DISTINCT d.stock_code) * 0.1))) THEN (15) ELSE 0 END) + CASE  WHEN ((count_star() FILTER (WHERE d.whale_signal) > 0)) THEN (10) ELSE 0 END) + CASE  WHEN ((count_star() FILTER (WHERE (d.change_percent > 0)) > count_star() FILTER (WHERE (d.change_percent < 0)))) THEN (15) ELSE 0 END) + CASE  WHEN ((count_star() FILTER (WHERE (d."close" >= d.vwma_20d)) > (count(DISTINCT d.stock_code) * 0.5))) THEN (10) ELSE 0 END) + CASE  WHEN ((count_star() FILTER (WHERE (d.volume > (d.ma20_volume * 1.5))) > (count(DISTINCT d.stock_code) * 0.1))) THEN (10) ELSE 0 END))) AS momentum_score FROM market.daily_transactions AS d LEFT JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)) GROUP BY d.trading_date, cp.sector;

-- ─────────────────────────────────────────────────────────────
-- market.vw_f_volume_profile
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_f_volume_profile AS WITH base AS (SELECT stock_code, trading_date, volume, "value", frequency, ma20_volume, avg_order_volume, ma50_avg_order_volume, aov_ratio_ma20, whale_signal AS raw_whale_signal, big_player_anomaly AS raw_big_player_anomaly, "close", change_percent, net_foreign_value FROM market.daily_transactions), with_metrics AS (SELECT *, round((CAST(volume AS DOUBLE) / "nullif"(frequency, 0)), 0) AS lot_per_tx, round((CAST(volume AS DOUBLE) / "nullif"(ma20_volume, 0)), 3) AS vol_ratio_ma20, round((avg_order_volume / "nullif"(ma50_avg_order_volume, 0)), 3) AS aov_ratio_ma50, ("value" >= 500000000) AS meets_value_threshold, (volume >= 100000) AS meets_volume_threshold FROM base)SELECT stock_code, trading_date, volume, "value", frequency, ma20_volume, avg_order_volume, ma50_avg_order_volume, aov_ratio_ma20, aov_ratio_ma50, lot_per_tx, vol_ratio_ma20, meets_value_threshold, meets_volume_threshold, CASE  WHEN ((NOT meets_volume_threshold)) THEN ('THIN') WHEN ((vol_ratio_ma20 >= 3.0)) THEN ('SPIKE') WHEN ((vol_ratio_ma20 >= 1.5)) THEN ('ACTIVE') WHEN ((vol_ratio_ma20 >= 0.5)) THEN ('NORMAL') ELSE 'THIN' END AS vol_tier, CASE  WHEN ((NOT meets_value_threshold)) THEN ('NOISE') WHEN ((aov_ratio_ma20 >= 5.0)) THEN ('ULTRA') WHEN ((aov_ratio_ma20 >= 3.0)) THEN ('EXTREME') WHEN ((aov_ratio_ma20 >= 2.0)) THEN ('STRONG') WHEN ((aov_ratio_ma20 >= 1.5)) THEN ('ELEVATED') WHEN ((aov_ratio_ma20 >= 0.8)) THEN ('NORMAL') ELSE 'WEAK' END AS aov_tier, ((aov_ratio_ma20 >= 2.0) AND meets_value_threshold AND meets_volume_threshold AND (ma50_avg_order_volume > 0)) AS clean_whale_signal, ((aov_ratio_ma20 >= 3.0) AND ("value" >= 2000000000) AND meets_volume_threshold AND (ma50_avg_order_volume > 0)) AS clean_big_player_anomaly, ((vol_ratio_ma20 >= 1.5) AND (aov_ratio_ma20 >= 1.5) AND meets_value_threshold) AS dual_spike_flag, ((aov_ratio_ma20 >= 2.0) AND (abs(change_percent) <= 2.0) AND meets_value_threshold AND meets_volume_threshold) AS stealth_flag, ((aov_ratio_ma20 >= 2.0) AND (change_percent >= 2.0) AND (net_foreign_value < 0) AND meets_value_threshold) AS distribution_flag, raw_whale_signal, raw_big_player_anomaly, change_percent, "close", net_foreign_value FROM with_metrics;

-- ─────────────────────────────────────────────────────────────
-- market.vw_group_broker_stance
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_group_broker_stance AS WITH latest_date AS (SELECT max(trading_date) AS max_date FROM market.daily_transactions), b7 AS (SELECT cp.group_name, ba.broker_code, ba.broker_name, round((sum(ba."value") / 1000000000.0), 2) AS net_7d_miliar, count(DISTINCT ba.stock_code) AS stocks_7d FROM main.broker_activity AS ba INNER JOIN market.company_profile AS cp ON ((ba.stock_code = cp.stock_code)) WHERE ((ba.date >= ((SELECT max_date FROM latest_date) - CAST('7 days' AS INTERVAL))) AND (cp.group_name != 'Others')) GROUP BY cp.group_name, ba.broker_code, ba.broker_name), b30 AS (SELECT cp.group_name, ba.broker_code, round((sum(ba."value") / 1000000000.0), 2) AS net_30d_miliar FROM main.broker_activity AS ba INNER JOIN market.company_profile AS cp ON ((ba.stock_code = cp.stock_code)) WHERE ((ba.date >= ((SELECT max_date FROM latest_date) - CAST('30 days' AS INTERVAL))) AND (cp.group_name != 'Others')) GROUP BY cp.group_name, ba.broker_code), grp_consensus AS (SELECT group_name, count(CASE  WHEN ((net_7d_miliar > 0)) THEN (1) ELSE NULL END) AS buy_brokers, count(CASE  WHEN ((net_7d_miliar < 0)) THEN (1) ELSE NULL END) AS sell_brokers, count_star() AS total_brokers, round(sum(net_7d_miliar), 2) AS group_net_7d_miliar FROM b7 GROUP BY group_name)SELECT b7.group_name, b7.broker_code, b7.broker_name, b7.net_7d_miliar, COALESCE(b30.net_30d_miliar, 0) AS net_30d_miliar, b7.stocks_7d, gc.buy_brokers, gc.sell_brokers, gc.total_brokers, gc.group_net_7d_miliar, round(((100.0 * gc.buy_brokers) / "nullif"(gc.total_brokers, 0)), 1) AS buy_consensus_pct, CASE  WHEN ((round(((100.0 * gc.buy_brokers) / "nullif"(gc.total_brokers, 0)), 1) >= 70)) THEN ('STRONG_BUY') WHEN ((round(((100.0 * gc.buy_brokers) / "nullif"(gc.total_brokers, 0)), 1) >= 55)) THEN ('BUY') WHEN ((round(((100.0 * gc.buy_brokers) / "nullif"(gc.total_brokers, 0)), 1) >= 45)) THEN ('NEUTRAL') WHEN ((round(((100.0 * gc.buy_brokers) / "nullif"(gc.total_brokers, 0)), 1) >= 30)) THEN ('SELL') ELSE 'STRONG_SELL' END AS broker_consensus, CASE  WHEN (((b7.net_7d_miliar > 0) AND (COALESCE(b30.net_30d_miliar, 0) < 0))) THEN ('NEW_ENTRY') WHEN (((b7.net_7d_miliar < 0) AND (COALESCE(b30.net_30d_miliar, 0) > 0))) THEN ('NEW_EXIT') WHEN (((b7.net_7d_miliar > 0) AND (COALESCE(b30.net_30d_miliar, 0) > 0))) THEN ('CONSISTENT_BUY') WHEN (((b7.net_7d_miliar < 0) AND (COALESCE(b30.net_30d_miliar, 0) < 0))) THEN ('CONSISTENT_SELL') ELSE 'MIXED' END AS rotation_signal FROM b7 LEFT JOIN b30 ON (((b7.group_name = b30.group_name) AND (b7.broker_code = b30.broker_code))) LEFT JOIN grp_consensus AS gc ON ((b7.group_name = gc.group_name)) ORDER BY b7.group_name, b7.net_7d_miliar DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_group_foreign_flow
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_group_foreign_flow AS WITH group_daily AS (SELECT cp.group_name, d.trading_date, sum(d.net_foreign_value) AS daily_foreign, sum(d."value") AS daily_value FROM market.daily_transactions AS d INNER JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)) WHERE ((cp.group_name != 'Others') AND (d.trading_date >= ((SELECT max(trading_date) FROM market.daily_transactions) - CAST('30 days' AS INTERVAL)))) GROUP BY cp.group_name, d.trading_date)SELECT group_name, sum(daily_foreign) AS total_foreign_30d, sum(daily_value) AS total_value_30d, count_star() AS active_days, round(avg(daily_foreign), 0) AS avg_daily_foreign, sum(CASE  WHEN ((daily_foreign > 0)) THEN (daily_foreign) ELSE 0 END) AS inflow, sum(CASE  WHEN ((daily_foreign < 0)) THEN (abs(daily_foreign)) ELSE 0 END) AS outflow, CASE  WHEN ((sum(daily_foreign) > 100000000000)) THEN ('🔥 MASSIVE INFLOW') WHEN ((sum(daily_foreign) > 10000000000)) THEN ('📈 INFLOW') WHEN ((sum(daily_foreign) < -100000000000)) THEN ('🔻 MASSIVE OUTFLOW') WHEN ((sum(daily_foreign) < -10000000000)) THEN ('📉 OUTFLOW') ELSE '➖ NEUTRAL' END AS flow_signal FROM group_daily GROUP BY group_name ORDER BY total_foreign_30d DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_group_leader_laggard
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_group_leader_laggard AS WITH latest_date AS (SELECT max(trading_date) AS max_date FROM market.daily_transactions), stock_daily AS (SELECT d.stock_code, d."close", d.change_percent, d."value", d.net_foreign_value, d.whale_signal, d.big_player_anomaly, d.aov_ratio_ma20, cp.group_name, cp.sector, cp.free_float FROM market.daily_transactions AS d INNER JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)) WHERE ((d.trading_date = (SELECT max_date FROM latest_date)) AND (cp.group_name != 'Others'))), group_avg AS (SELECT group_name, round(avg(change_percent), 2) AS grp_avg_chg, count_star() AS grp_total_stocks FROM stock_daily GROUP BY group_name), stock_rel AS (SELECT s.*, g.grp_avg_chg, g.grp_total_stocks, round((s.change_percent - g.grp_avg_chg), 2) AS relative_perf FROM stock_daily AS s INNER JOIN group_avg AS g ON ((s.group_name = g.group_name))), ksei_latest AS (SELECT Code, round(((((((Local_CP_Chg_Val + Local_PF_Chg_Val) + Local_IB_Chg_Val) + Foreign_CP_Chg_Val) + Foreign_PF_Chg_Val) + Foreign_IB_Chg_Val) / 1000000000.0), 2) AS ksei_smart_miliar FROM ksei.monthly_snapshot WHERE (Date = (SELECT max(Date) FROM ksei.monthly_snapshot))), broker_7d AS (SELECT "left"(ba.stock_code, 4) AS stock_code, round((sum(ba."value") / 1000000000.0), 2) AS broker_net_miliar FROM main.broker_activity AS ba INNER JOIN main.broker_classification AS bc ON ((bc.broker_code = ba.broker_code)) WHERE ((CAST(ba.date AS "DATE") >= ((SELECT max(trading_date) FROM market.daily_transactions) - CAST('7 days' AS INTERVAL))) AND (upper(bc.category) IN ('FOREIGN', 'LOCAL_INST'))) GROUP BY "left"(ba.stock_code, 4))SELECT sr.group_name, sr.stock_code, sr.sector, sr."close", round(sr.change_percent, 2) AS change_pct, sr.grp_avg_chg, sr.relative_perf, sr.whale_signal, sr.big_player_anomaly, round((sr.net_foreign_value / 1000000.0), 2) AS net_foreign_juta, sr.aov_ratio_ma20, sr.free_float, COALESCE(k.ksei_smart_miliar, 0) AS ksei_smart_miliar, COALESCE(b.broker_net_miliar, 0) AS broker_net_7d_miliar, CASE  WHEN (((sr.relative_perf >= 2) AND (sr.whale_signal OR (sr.net_foreign_value > 0) OR (COALESCE(k.ksei_smart_miliar, 0) > 0)))) THEN ('LEADER') WHEN ((sr.relative_perf >= 2)) THEN ('OUTPERFORMER') WHEN (((sr.relative_perf <= -2) AND (sr.whale_signal OR (COALESCE(k.ksei_smart_miliar, 0) > 0) OR (COALESCE(b.broker_net_miliar, 0) > 0)))) THEN ('CATCH_UP_CANDIDATE') WHEN ((sr.relative_perf <= -2)) THEN ('LAGGARD') ELSE 'INLINE' END AS stock_role, CASE  WHEN (((sr.relative_perf <= -2) AND (COALESCE(k.ksei_smart_miliar, 0) > 0) AND (COALESCE(b.broker_net_miliar, 0) > 0))) THEN ('HIGH') WHEN (((sr.relative_perf <= -2) AND ((COALESCE(k.ksei_smart_miliar, 0) > 0) OR sr.whale_signal))) THEN ('MEDIUM') ELSE 'LOW' END AS catchup_conviction FROM stock_rel AS sr LEFT JOIN ksei_latest AS k ON ((sr.stock_code = k.Code)) LEFT JOIN broker_7d AS b ON ((sr.stock_code = b.stock_code)) ORDER BY sr.group_name, sr.relative_perf DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_group_multi_period_perf
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_group_multi_period_perf AS WITH latest_date AS (SELECT max(trading_date) AS max_date FROM market.daily_transactions), stock_group AS (SELECT d.stock_code, d.trading_date, d.change_percent, d."value", d.net_foreign_value, d.whale_signal, d.big_player_anomaly, cp.group_name FROM market.daily_transactions AS d INNER JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)) WHERE (cp.group_name != 'Others')), d1 AS (SELECT group_name, round(avg(change_percent), 2) AS perf_1d, sum("value") AS value_1d, sum(net_foreign_value) AS foreign_1d, count(CASE  WHEN (whale_signal) THEN (1) ELSE NULL END) AS whale_1d, count(CASE  WHEN (big_player_anomaly) THEN (1) ELSE NULL END) AS anomaly_1d FROM stock_group WHERE (trading_date = (SELECT max_date FROM latest_date)) GROUP BY group_name), d5 AS (SELECT group_name, round(avg(change_percent), 2) AS perf_5d_avg, round(((sum("value") / 5.0) / 1000000000.0), 2) AS avg_val_5d_miliar, round((sum(net_foreign_value) / 1000000000.0), 2) AS foreign_net_5d_miliar FROM stock_group WHERE (trading_date >= ((SELECT max_date FROM latest_date) - CAST('7 days' AS INTERVAL))) GROUP BY group_name), d20 AS (SELECT group_name, round(avg(change_percent), 2) AS perf_20d_avg, round(((sum("value") / 20.0) / 1000000000.0), 2) AS avg_val_20d_miliar, round((sum(net_foreign_value) / 1000000000.0), 2) AS foreign_net_20d_miliar FROM stock_group WHERE (trading_date >= ((SELECT max_date FROM latest_date) - CAST('30 days' AS INTERVAL))) GROUP BY group_name), d60 AS (SELECT group_name, round(avg(change_percent), 2) AS perf_60d_avg, round((sum(net_foreign_value) / 1000000000.0), 2) AS foreign_net_60d_miliar FROM stock_group WHERE (trading_date >= ((SELECT max_date FROM latest_date) - CAST('90 days' AS INTERVAL))) GROUP BY group_name), market_avg AS (SELECT round(avg(change_percent), 2) AS mkt_avg_1d FROM market.daily_transactions WHERE (trading_date = (SELECT max_date FROM latest_date)))SELECT d1.group_name, d1.perf_1d, d5.perf_5d_avg, d20.perf_20d_avg, d60.perf_60d_avg, d1.whale_1d, d1.anomaly_1d, round((d1.value_1d / 1000000000.0), 2) AS value_1d_miliar, d5.avg_val_5d_miliar, d20.avg_val_20d_miliar, round((d1.foreign_1d / 1000000000.0), 2) AS foreign_net_1d_miliar, d5.foreign_net_5d_miliar, d20.foreign_net_20d_miliar, d60.foreign_net_60d_miliar, CASE  WHEN ((d5.perf_5d_avg > (d20.perf_20d_avg + 0.5))) THEN ('ACCELERATING') WHEN ((d5.perf_5d_avg < (d20.perf_20d_avg - 0.5))) THEN ('DECELERATING') ELSE 'STABLE' END AS momentum_state, CASE  WHEN (((d5.foreign_net_5d_miliar > 0) AND (d20.foreign_net_20d_miliar > 0))) THEN ('INFLOW_KONSISTEN') WHEN (((d5.foreign_net_5d_miliar > 0) AND (d20.foreign_net_20d_miliar <= 0))) THEN ('INFLOW_BARU') WHEN (((d5.foreign_net_5d_miliar < 0) AND (d20.foreign_net_20d_miliar < 0))) THEN ('OUTFLOW_KONSISTEN') WHEN (((d5.foreign_net_5d_miliar < 0) AND (d20.foreign_net_20d_miliar >= 0))) THEN ('OUTFLOW_BARU') ELSE 'MIXED' END AS foreign_flow_trend, round((d1.perf_1d - m.mkt_avg_1d), 2) AS rs_vs_market_1d FROM d1 LEFT JOIN d5 ON ((d1.group_name = d5.group_name)) LEFT JOIN d20 ON ((d1.group_name = d20.group_name)) LEFT JOIN d60 ON ((d1.group_name = d60.group_name)) CROSS JOIN market_avg AS m ORDER BY d1.perf_1d DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_group_phase_composite
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_group_phase_composite AS WITH gs AS (SELECT * FROM market.vw_group_summary), mp AS (SELECT * FROM market.vw_group_multi_period_perf), ksm AS (SELECT * FROM ksei.vw_group_ksei_smart_money), ff AS (SELECT * FROM market.vw_group_foreign_flow), bc AS (SELECT group_name, max(buy_consensus_pct) AS broker_buy_pct, max(broker_consensus) AS broker_consensus, round(sum(CASE  WHEN ((net_7d_miliar > 0)) THEN (net_7d_miliar) ELSE 0 END), 2) AS broker_buy_7d, round(sum(CASE  WHEN ((net_7d_miliar < 0)) THEN (abs(net_7d_miliar)) ELSE 0 END), 2) AS broker_sell_7d, max(group_net_7d_miliar) AS broker_net_7d_miliar FROM market.vw_group_broker_stance GROUP BY group_name), scored AS (SELECT gs.group_name, gs.total_stocks, gs.avg_change_pct AS perf_1d, mp.perf_5d_avg, mp.perf_20d_avg, mp.perf_60d_avg, mp.momentum_state, mp.rs_vs_market_1d, mp.foreign_flow_trend, mp.foreign_net_1d_miliar, mp.foreign_net_5d_miliar, mp.foreign_net_20d_miliar, ksm.local_smart_miliar, ksm.foreign_smart_miliar, ksm.total_smart_miliar, ksm.local_retail_miliar, ksm.local_cp_miliar, ksm.local_pf_miliar, ksm.local_ib_miliar, ksm.foreign_cp_miliar, ksm.smart_money_trend, ksm.divergence_signal, ksm.institution_alignment, ksm.ksei_conviction_score, ksm.konsisten_3_bulan, ksm.group_top_buyer, ff.flow_signal AS foreign_daily_signal, (ff.total_foreign_30d / 1000000000.0) AS foreign_30d_miliar, COALESCE(bc.broker_buy_pct, 50) AS broker_buy_pct, COALESCE(bc.broker_consensus, 'NEUTRAL') AS broker_consensus, COALESCE(bc.broker_net_7d_miliar, 0) AS broker_net_7d_miliar, gs.whale_count, gs.anomaly_count, gs.stocks_list, CAST(least(100, greatest(0, (((((COALESCE(ksm.ksei_conviction_score, 0) * 0.35) + CASE  WHEN ((COALESCE(mp.perf_20d_avg, 0) > 3)) THEN (25) WHEN ((COALESCE(mp.perf_20d_avg, 0) > 1)) THEN (18) WHEN ((COALESCE(mp.perf_20d_avg, 0) > 0)) THEN (10) WHEN ((COALESCE(mp.perf_20d_avg, 0) > -1)) THEN (5) ELSE 0 END) + CASE  WHEN ((COALESCE((ff.total_foreign_30d / 1000000000.0), 0) > 1000)) THEN (20) WHEN ((COALESCE((ff.total_foreign_30d / 1000000000.0), 0) > 200)) THEN (14) WHEN ((COALESCE((ff.total_foreign_30d / 1000000000.0), 0) > 0)) THEN (7) ELSE 0 END) + CASE  WHEN ((COALESCE(bc.broker_buy_pct, 50) >= 70)) THEN (15) WHEN ((COALESCE(bc.broker_buy_pct, 50) >= 55)) THEN (9) WHEN ((COALESCE(bc.broker_buy_pct, 50) >= 45)) THEN (4) ELSE 0 END) + CASE  WHEN ((COALESCE(gs.whale_count, 0) >= 3)) THEN (5) WHEN ((COALESCE(gs.whale_count, 0) >= 1)) THEN (3) ELSE 0 END))) AS INTEGER) AS composite_score FROM gs LEFT JOIN mp ON ((gs.group_name = mp.group_name)) LEFT JOIN ksm ON ((gs.group_name = ksm.group_name)) LEFT JOIN ff ON ((gs.group_name = ff.group_name)) LEFT JOIN bc ON ((gs.group_name = bc.group_name)))SELECT *, CASE  WHEN (((composite_score >= 75) AND (COALESCE(smart_money_trend, '') ~~ '%AKUMULASI%'))) THEN ('MARKUP') WHEN (((composite_score >= 60) AND (COALESCE(smart_money_trend, '') = 'MULAI_AKUMULASI'))) THEN ('EARLY MARKUP') WHEN (((composite_score >= 45) AND (COALESCE(total_smart_miliar, 0) > 0))) THEN ('AKUMULASI') WHEN (((composite_score < 30) AND (COALESCE(smart_money_trend, '') ~~ '%DISTRIBUSI%'))) THEN ('DISTRIBUSI') WHEN ((composite_score < 20)) THEN ('MARKDOWN') ELSE 'SIDEWAYS' END AS market_phase, CASE  WHEN ((composite_score >= 75)) THEN ('STRONG BUY GROUP') WHEN ((composite_score >= 60)) THEN ('BUY GROUP') WHEN ((composite_score >= 45)) THEN ('WATCH / ACCUMULATE') WHEN ((composite_score >= 30)) THEN ('AVOID / REDUCE') ELSE 'EXIT GROUP' END AS group_action_signal FROM scored ORDER BY composite_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_group_summary
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_group_summary AS WITH latest_date AS (SELECT max(trading_date) AS max_date FROM market.daily_transactions), group_stocks AS (SELECT cp.group_name, cp.stock_code, cp.sector, d."close", d.change_percent, d."value", d.volume, d.net_foreign_value, d.whale_signal, d.big_player_anomaly, d.aov_ratio_ma20 FROM market.company_profile AS cp LEFT JOIN market.daily_transactions AS d ON ((cp.stock_code = d.stock_code)) WHERE ((cp.group_name != 'Others') AND (d.trading_date = (SELECT max_date FROM latest_date))))SELECT group_name, count(DISTINCT stock_code) AS total_stocks, round(avg(change_percent), 2) AS avg_change_pct, sum("value") AS total_value, sum(net_foreign_value) AS total_foreign, count(CASE  WHEN ((change_percent > 0)) THEN (1) ELSE NULL END) AS gainers, count(CASE  WHEN ((change_percent < 0)) THEN (1) ELSE NULL END) AS losers, count(CASE  WHEN (whale_signal) THEN (1) ELSE NULL END) AS whale_count, count(CASE  WHEN (big_player_anomaly) THEN (1) ELSE NULL END) AS anomaly_count, round(avg(aov_ratio_ma20), 2) AS avg_aov, string_agg(stock_code, ', ' ORDER BY "value" DESC) AS stocks_list, least(100, greatest(0, ((((CASE  WHEN ((avg(change_percent) > 0)) THEN (25) ELSE -10 END + CASE  WHEN ((sum(net_foreign_value) > 0)) THEN (25) ELSE -10 END) + CASE  WHEN ((count(CASE  WHEN (whale_signal) THEN (1) ELSE NULL END) > 0)) THEN (20) ELSE 0 END) + CASE  WHEN ((count(CASE  WHEN ((change_percent > 0)) THEN (1) ELSE NULL END) > count(CASE  WHEN ((change_percent < 0)) THEN (1) ELSE NULL END))) THEN (15) ELSE 0 END) + CASE  WHEN ((avg(aov_ratio_ma20) >= 1.5)) THEN (15) ELSE 0 END))) AS momentum_score, CASE  WHEN ((momentum_score >= 60)) THEN ('🟢 STRONG') WHEN ((momentum_score >= 40)) THEN ('🟡 MODERATE') WHEN ((momentum_score >= 20)) THEN ('🟠 WEAK') ELSE '🔴 BEARISH' END AS group_signal FROM group_stocks GROUP BY group_name HAVING (count(DISTINCT stock_code) >= 2) ORDER BY momentum_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_market_summary
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_market_summary AS SELECT trading_date, count(DISTINCT stock_code) AS stock_count, sum("value") AS total_value, sum(volume) AS total_volume, sum(net_foreign_value) AS total_foreign_flow, count(CASE  WHEN (whale_signal) THEN (1) ELSE NULL END) AS whale_count, count(CASE  WHEN (big_player_anomaly) THEN (1) ELSE NULL END) AS anomaly_count, round(avg(change_percent), 2) AS avg_change_pct, count(CASE  WHEN ((change_percent > 0)) THEN (1) ELSE NULL END) AS gainers, count(CASE  WHEN ((change_percent < 0)) THEN (1) ELSE NULL END) AS losers FROM market.daily_transactions GROUP BY trading_date ORDER BY trading_date DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_aov_anomaly
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_aov_anomaly AS SELECT vp.stock_code, vp.trading_date, vp."close", vp.change_percent, vp.volume, vp."value", vp.frequency, vp.lot_per_tx, vp.avg_order_volume, vp.ma50_avg_order_volume, vp.aov_ratio_ma20, vp.aov_ratio_ma50, vp.aov_tier, vp.meets_value_threshold, vp.meets_volume_threshold, vp.clean_whale_signal, vp.clean_big_player_anomaly, vp.stealth_flag, vp.distribution_flag, vp.dual_spike_flag, vp.net_foreign_value, round((vp.net_foreign_value / 1000000000.0), 3) AS net_foreign_miliar, CASE  WHEN ((NOT vp.meets_value_threshold)) THEN ('NOISE') WHEN ((vp.clean_whale_signal AND (vp.net_foreign_value > 0) AND (abs(vp.change_percent) <= 2.0))) THEN ('FOREIGN_STEALTH_ACCUM') WHEN ((vp.clean_whale_signal AND (vp.net_foreign_value < 0) AND (vp.change_percent > 2.0))) THEN ('DISTRIBUTION_SIGNAL') WHEN ((vp.clean_big_player_anomaly AND (vp.net_foreign_value > 0))) THEN ('PRIME_INSTITUTIONAL_BUY') WHEN ((vp.clean_whale_signal AND (vp.net_foreign_value <= 0))) THEN ('LOCAL_WHALE') WHEN (((vp.aov_ratio_ma20 >= 1.5) AND vp.meets_value_threshold)) THEN ('ELEVATED_AOV') ELSE 'NORMAL' END AS aov_signal, sum(CASE  WHEN (vp.stealth_flag) THEN (1) ELSE 0 END) OVER (PARTITION BY vp.stock_code ORDER BY vp.trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS stealth_days_20d, sum(CASE  WHEN (vp.clean_whale_signal) THEN (1) ELSE 0 END) OVER (PARTITION BY vp.stock_code ORDER BY vp.trading_date ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS whale_days_5d FROM market.vw_f_volume_profile AS vp;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_breakout_technical
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_breakout_technical AS WITH latest AS (SELECT max(trading_date) AS d FROM market.daily_transactions), consol AS (SELECT stock_code, count_star() AS total_days, round(((max("close") / "nullif"(min("close"), 0)) - 1), 4) AS price_range_pct, stddev(change_percent) AS change_volatility FROM market.daily_transactions WHERE (trading_date >= ((SELECT d FROM latest) - CAST('19 days' AS INTERVAL))) GROUP BY stock_code)SELECT ph.stock_code, ph.trading_date, ph."close", ph.change_percent, ph.pct_from_52w_high, ph.pct_from_52w_low, ph.return_20d, ph.vwma_20d, (ph."close" >= ph.vwma_20d) AS above_vwma, round((((ph."close" - ph.vwma_20d) / "nullif"(ph.vwma_20d, 0)) * 100), 2) AS pct_above_vwma, vp.vol_ratio_ma20, vp.vol_tier, (vp.vol_ratio_ma20 >= 1.5) AS volume_confirming, c.price_range_pct, (c.price_range_pct <= 0.05) AS is_consolidating, c.change_volatility AS vol_20d, CASE  WHEN ((ph.pct_from_52w_high >= -2.0)) THEN ('IMMINENT') WHEN ((ph.pct_from_52w_high >= -5.0)) THEN ('NEAR') WHEN ((ph.pct_from_52w_high >= -10.0)) THEN ('APPROACHING') ELSE 'DISTANT' END AS breakout_proximity, least(10, (((CASE  WHEN ((ph.pct_from_52w_high >= -2.0)) THEN (4) WHEN ((ph.pct_from_52w_high >= -5.0)) THEN (2) ELSE 0 END + CASE  WHEN ((ph."close" >= ph.vwma_20d)) THEN (2) ELSE 0 END) + CASE  WHEN ((vp.vol_ratio_ma20 >= 1.5)) THEN (2) ELSE 0 END) + CASE  WHEN ((c.price_range_pct <= 0.05)) THEN (2) ELSE 0 END)) AS breakout_readiness_score FROM market.vw_f_price_history AS ph INNER JOIN market.vw_f_volume_profile AS vp ON (((ph.stock_code = vp.stock_code) AND (ph.trading_date = vp.trading_date))) INNER JOIN consol AS c ON ((ph.stock_code = c.stock_code)) WHERE (ph.trading_date = (SELECT d FROM latest));

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_broker_accumulation
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_broker_accumulation AS SELECT cr.stock_code, cr.foreign_net_1d, cr.foreign_net_5d, cr.foreign_net_20d, cr.foreign_net_30d, cr.inst_net_1d, cr.inst_net_5d, cr.inst_net_20d, cr.inst_net_30d, cr.retail_net_5d, cr.retail_net_20d, cr.prime_net_5d, cr.prime_net_20d, cr.foreign_trend_5d_vs_20d, CASE  WHEN (((cr.foreign_net_5d > 0) AND (cr.foreign_net_20d > 0) AND (cr.foreign_net_30d > 0))) THEN ('MATURE_ACCUMULATION') WHEN (((cr.foreign_net_5d > 0) AND (cr.foreign_net_20d > 0))) THEN ('BUILDING_ACCUMULATION') WHEN (((cr.foreign_net_5d > 0) AND (cr.foreign_net_20d <= 0))) THEN ('EARLY_ACCUMULATION') WHEN (((cr.foreign_net_5d < 0) AND (cr.foreign_net_20d > 0))) THEN ('FADING_ACCUMULATION') WHEN (((cr.foreign_net_5d < 0) AND (cr.foreign_net_20d < 0))) THEN ('DISTRIBUTION') ELSE 'NEUTRAL' END AS accumulation_phase, CASE  WHEN ((((cr.foreign_net_5d > 0) OR (cr.inst_net_5d > 0)) AND (cr.retail_net_5d < 0))) THEN ('SMART_BUY_RETAIL_SELL') WHEN ((((cr.foreign_net_5d < 0) OR (cr.inst_net_5d < 0)) AND (cr.retail_net_5d > 0))) THEN ('SMART_SELL_RETAIL_BUY') WHEN (((cr.foreign_net_5d > 0) AND (cr.inst_net_5d > 0) AND (cr.retail_net_5d > 0))) THEN ('ALL_BUYING') WHEN (((cr.foreign_net_5d < 0) AND (cr.inst_net_5d < 0))) THEN ('INSTITUTIONAL_EXIT') ELSE 'MIXED' END AS flow_regime, ((cr.prime_net_5d > 0) AND (cr.foreign_net_5d > 0)) AS prime_confirms_foreign, round((cr.foreign_net_30d + cr.inst_net_30d), 3) AS smart_accumulated_30d_miliar FROM main.vw_f_broker_category_rolling AS cr;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_broker_convergence
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_broker_convergence AS SELECT stock_code, count(DISTINCT CASE  WHEN (((category = 'FOREIGN') AND is_buyer_5d)) THEN (broker_code) ELSE NULL END) AS foreign_buyers_5d, count(DISTINCT CASE  WHEN (((category = 'FOREIGN') AND (NOT is_buyer_5d))) THEN (broker_code) ELSE NULL END) AS foreign_sellers_5d, count(DISTINCT CASE  WHEN (((category = 'LOCAL_INST') AND is_buyer_5d)) THEN (broker_code) ELSE NULL END) AS inst_buyers_5d, count(DISTINCT CASE  WHEN (((category = 'LOCAL_INST') AND (NOT is_buyer_5d))) THEN (broker_code) ELSE NULL END) AS inst_sellers_5d, round(sum(CASE  WHEN ((category = 'FOREIGN')) THEN (net_5d) ELSE 0 END), 3) AS foreign_net_5d, round(sum(CASE  WHEN ((category = 'LOCAL_INST')) THEN (net_5d) ELSE 0 END), 3) AS inst_net_5d, count(DISTINCT CASE  WHEN ((is_buyer_5d AND (category IN ('FOREIGN', 'LOCAL_INST')))) THEN (broker_code) ELSE NULL END) AS inst_foreign_buyers_5d, CASE  WHEN ((count(DISTINCT CASE  WHEN ((is_buyer_5d AND (category = 'FOREIGN'))) THEN (broker_code) ELSE NULL END) >= 5)) THEN ('STRONG') WHEN ((count(DISTINCT CASE  WHEN ((is_buyer_5d AND (category = 'FOREIGN'))) THEN (broker_code) ELSE NULL END) >= 3)) THEN ('MODERATE') WHEN ((count(DISTINCT CASE  WHEN ((is_buyer_5d AND (category = 'FOREIGN'))) THEN (broker_code) ELSE NULL END) >= 1)) THEN ('WEAK') ELSE 'NONE' END AS foreign_convergence_level, ((count(DISTINCT CASE  WHEN ((is_buyer_5d AND (category = 'FOREIGN'))) THEN (broker_code) ELSE NULL END) >= 2) AND (count(DISTINCT CASE  WHEN ((is_buyer_5d AND (category = 'LOCAL_INST'))) THEN (broker_code) ELSE NULL END) >= 1)) AS dual_category_convergence, CASE  WHEN (((sum(CASE  WHEN ((category = 'FOREIGN')) THEN (net_5d) ELSE 0 END) > 0) AND (sum(CASE  WHEN ((category = 'LOCAL_INST')) THEN (net_5d) ELSE 0 END) > 0))) THEN ('FOREIGN_INST_ALIGNED_BUY') WHEN (((sum(CASE  WHEN ((category = 'FOREIGN')) THEN (net_5d) ELSE 0 END) < 0) AND (sum(CASE  WHEN ((category = 'LOCAL_INST')) THEN (net_5d) ELSE 0 END) < 0))) THEN ('FOREIGN_INST_ALIGNED_SELL') WHEN (((sum(CASE  WHEN ((category = 'FOREIGN')) THEN (net_5d) ELSE 0 END) > 0) AND (sum(CASE  WHEN ((category = 'LOCAL_INST')) THEN (net_5d) ELSE 0 END) < 0))) THEN ('FOREIGN_BUY_INST_SELL') WHEN (((sum(CASE  WHEN ((category = 'FOREIGN')) THEN (net_5d) ELSE 0 END) < 0) AND (sum(CASE  WHEN ((category = 'LOCAL_INST')) THEN (net_5d) ELSE 0 END) > 0))) THEN ('INST_BUY_FOREIGN_SELL') ELSE 'MIXED' END AS category_alignment FROM main.vw_f_broker_net_rolling GROUP BY stock_code;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_broker_distribution
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_broker_distribution AS SELECT cr.stock_code, cr.foreign_net_5d, cr.foreign_net_20d, cr.inst_net_5d, cr.inst_net_20d, cr.retail_net_5d, cr.retail_net_20d, ((cr.foreign_net_5d < 0) AND (cr.retail_net_5d > 0)) AS distribution_to_retail, CASE  WHEN (((cr.foreign_net_5d < 0) AND (cr.foreign_net_20d < 0) AND (cr.inst_net_5d < 0) AND (cr.retail_net_5d > 0))) THEN ('HIGH') WHEN (((cr.foreign_net_5d < 0) AND (cr.foreign_net_20d < 0) AND (cr.retail_net_5d > 0))) THEN ('MEDIUM') WHEN (((cr.foreign_net_5d < 0) AND (cr.retail_net_5d > 0))) THEN ('LOW') ELSE 'NONE' END AS distribution_intensity, ((cr.foreign_net_5d < 0) AND (cr.foreign_net_20d > 0)) AS foreign_exit_signal, ((cr.inst_net_5d < 0) AND (cr.inst_net_20d > 0)) AS inst_exit_signal, CASE  WHEN (((cr.foreign_net_30d < 0) AND (cr.foreign_net_20d < 0) AND (cr.foreign_net_5d < 0))) THEN ('PROLONGED') WHEN (((cr.foreign_net_20d < 0) AND (cr.foreign_net_5d < 0))) THEN ('DEVELOPING') WHEN ((cr.foreign_net_5d < 0)) THEN ('EARLY') ELSE 'NONE' END AS distribution_stage FROM main.vw_f_broker_category_rolling AS cr WHERE ((cr.foreign_net_5d < 0) OR (cr.inst_net_5d < 0));

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_foreign_accumulation
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_foreign_accumulation AS WITH daily_value AS (SELECT stock_code, avg("value") FILTER (WHERE ("value" > 0)) AS avg_daily_value FROM market.daily_transactions GROUP BY stock_code)SELECT ff.stock_code, ff.trading_date, ff.net_foreign_value, ff.net_foreign_5d, ff.net_foreign_20d, ff.net_foreign_60d, ff.net_foreign_5d_miliar, ff.net_foreign_20d_miliar, ff.net_foreign_60d_miliar, ff.foreign_is_buyer, ff.foreign_buy_days_20d, ff.stealth_day_flag, round(((CAST(ff.foreign_buy_days_20d AS DOUBLE) / 20.0) * 100), 1) AS foreign_buy_pct_20d, round(((abs(ff.net_foreign_value) / "nullif"(dv.avg_daily_value, 0)) * 100), 1) AS flow_intensity_pct, CASE  WHEN (((ff.net_foreign_20d > 0) AND (ff.foreign_buy_days_20d >= 15))) THEN ('HEAVY') WHEN (((ff.net_foreign_20d > 0) AND (ff.foreign_buy_days_20d >= 10))) THEN ('MODERATE') WHEN (((ff.net_foreign_20d > 0) AND (ff.foreign_buy_days_20d >= 5))) THEN ('LIGHT') WHEN (((ff.net_foreign_20d <= 0) AND (ff.foreign_buy_days_20d <= 5))) THEN ('DISTRIBUTING') ELSE 'MIXED' END AS accumulation_intensity, CASE  WHEN (((ff.net_foreign_5d > 0) AND (ff.net_foreign_20d > 0) AND (ff.net_foreign_60d > 0))) THEN ('CONSISTENT_INFLOW') WHEN (((ff.net_foreign_5d > 0) AND (ff.net_foreign_20d > 0))) THEN ('BUILDING_INFLOW') WHEN (((ff.net_foreign_5d > 0) AND (ff.net_foreign_20d <= 0))) THEN ('NEW_INFLOW') WHEN (((ff.net_foreign_5d < 0) AND (ff.net_foreign_20d < 0) AND (ff.net_foreign_60d < 0))) THEN ('CONSISTENT_OUTFLOW') WHEN (((ff.net_foreign_5d < 0) AND (ff.net_foreign_20d >= 0))) THEN ('NEW_OUTFLOW') ELSE 'MIXED' END AS flow_direction, ((ff.net_foreign_5d > 0) AND (ff.net_foreign_20d < 0)) AS is_reversal_buy, ((ff.net_foreign_5d < 0) AND (ff.net_foreign_20d > 0)) AS is_reversal_sell FROM market.vw_f_foreign_flow_daily AS ff INNER JOIN daily_value AS dv ON ((ff.stock_code = dv.stock_code));

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_foreign_divergence
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_foreign_divergence AS SELECT ff.stock_code, ff.trading_date, ff.net_foreign_value, ff.net_foreign_5d_miliar, ff.net_foreign_20d_miliar, ff.change_percent, ph.return_5d, ph.return_20d, CASE  WHEN ((ff.net_foreign_5d > 0)) THEN ('BUYING') ELSE 'SELLING' END AS foreign_dir_5d, CASE  WHEN ((ph.return_5d > 0)) THEN ('UP') ELSE 'DOWN' END AS price_dir_5d, CASE  WHEN (((ff.net_foreign_5d > 0) AND (ff.net_foreign_20d > 0) AND (ph.return_5d <= 1.0))) THEN ('STEALTH_ACCUMULATION') WHEN (((ff.net_foreign_5d > 0) AND (ph.return_5d < -5.0))) THEN ('BUYING_THE_DIP') WHEN (((ff.net_foreign_5d > 0) AND (ph.return_5d > 2.0))) THEN ('CONFIRMED_UPTREND') WHEN (((ff.net_foreign_5d < 0) AND (ph.return_5d > 2.0))) THEN ('DISTRIBUTION_WHILE_UP') WHEN (((ff.net_foreign_5d < 0) AND (ph.return_5d < -2.0))) THEN ('CONFIRMED_DOWNTREND') WHEN (((ff.net_foreign_5d < 0) AND (ff.net_foreign_20d > 0))) THEN ('FOREIGN_RETREAT') ELSE 'NEUTRAL' END AS divergence_type, ((ff.net_foreign_5d > 0) AND (ff.net_foreign_20d > 0) AND (ph.return_20d BETWEEN -5.0 AND 5.0)) AS is_stealth_quality, round(ff.net_foreign_5d_miliar, 3) AS net_5d_miliar, round(ff.net_foreign_20d_miliar, 3) AS net_20d_miliar FROM market.vw_f_foreign_flow_daily AS ff INNER JOIN market.vw_f_price_history AS ph ON (((ff.stock_code = ph.stock_code) AND (ff.trading_date = ph.trading_date)));

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_foreign_sector_rotation
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_foreign_sector_rotation AS WITH latest AS (SELECT max(trading_date) AS d FROM market.daily_transactions), today AS (SELECT sector, net_foreign_miliar AS foreign_today, rank() OVER (ORDER BY net_foreign_miliar DESC) AS rank_today FROM market.vw_f_sector_daily WHERE (trading_date = (SELECT d FROM latest))), five_d AS (SELECT sector, sum(net_foreign_miliar) AS foreign_5d, rank() OVER (ORDER BY sum(net_foreign_miliar) DESC) AS rank_5d FROM market.vw_f_sector_daily WHERE (trading_date >= ((SELECT d FROM latest) - CAST('4 days' AS INTERVAL))) GROUP BY sector), twenty_d AS (SELECT sector, sum(net_foreign_miliar) AS foreign_20d FROM market.vw_f_sector_daily WHERE (trading_date >= ((SELECT d FROM latest) - CAST('19 days' AS INTERVAL))) GROUP BY sector)SELECT t.sector, t.foreign_today, t.rank_today, f.foreign_5d, f.rank_5d, tw.foreign_20d, (f.rank_5d - t.rank_today) AS rank_change_1d_vs_5d, CASE  WHEN (((t.foreign_today > 0) AND (f.foreign_5d > 0) AND (tw.foreign_20d > 0))) THEN ('CONSISTENT_INFLOW') WHEN (((t.foreign_today > 0) AND (f.foreign_5d > 0) AND (tw.foreign_20d <= 0))) THEN ('NEW_ROTATION_IN') WHEN (((t.foreign_today < 0) AND (f.foreign_5d < 0) AND (tw.foreign_20d < 0))) THEN ('CONSISTENT_OUTFLOW') WHEN (((t.foreign_today < 0) AND (tw.foreign_20d > 0))) THEN ('ROTATING_OUT') ELSE 'MIXED' END AS rotation_signal FROM today AS t INNER JOIN five_d AS f ON ((t.sector = f.sector)) INNER JOIN twenty_d AS tw ON ((t.sector = tw.sector)) ORDER BY t.rank_today;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_group_momentum
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_group_momentum AS WITH mkt AS (SELECT trading_date, avg_change_pct AS mkt_chg FROM market.vw_f_market_breadth), with_roll AS (SELECT gd.*, m.mkt_chg, round((gd.avg_change_pct - m.mkt_chg), 3) AS vs_market, sum(gd.net_foreign_miliar) OVER (PARTITION BY gd.group_name ORDER BY gd.trading_date ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS foreign_net_5d, avg(gd.avg_change_pct) OVER (PARTITION BY gd.group_name ORDER BY gd.trading_date ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS return_5d_avg, avg(gd.avg_change_pct) OVER (PARTITION BY gd.group_name ORDER BY gd.trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS return_20d_avg FROM market.vw_f_group_daily AS gd INNER JOIN mkt AS m ON ((gd.trading_date = m.trading_date)))SELECT trading_date, group_name, stock_count, avg_change_pct, vs_market, net_foreign_miliar, foreign_net_5d, return_5d_avg, return_20d_avg, whale_count, anomaly_count, momentum_score, leader_stock, laggard_stock, most_active_stock, CASE  WHEN ((return_5d_avg > (return_20d_avg + 1.0))) THEN ('ACCELERATING') WHEN ((return_5d_avg > return_20d_avg)) THEN ('BUILDING') WHEN ((return_5d_avg < (return_20d_avg - 1.0))) THEN ('DECELERATING') WHEN ((return_5d_avg < return_20d_avg)) THEN ('FADING') ELSE 'STABLE' END AS momentum_state, CASE  WHEN (((foreign_net_5d > 0) AND (lag(foreign_net_5d, 5) OVER (PARTITION BY group_name ORDER BY trading_date) <= 0))) THEN ('ENTERING') WHEN (((foreign_net_5d < 0) AND (lag(foreign_net_5d, 5) OVER (PARTITION BY group_name ORDER BY trading_date) >= 0))) THEN ('EXITING') WHEN ((foreign_net_5d > 0)) THEN ('HOLDING_BUY') WHEN ((foreign_net_5d < 0)) THEN ('HOLDING_SELL') ELSE 'NEUTRAL' END AS rotation_signal FROM with_roll;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_market_breadth_signal
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_market_breadth_signal AS SELECT mr.trading_date, mr.breadth_score, mr.breadth_5d, mr.breadth_20d, mr.market_regime, mr.foreign_stance, mr.regime_changed_today, mr.foreign_today, mr.foreign_5d_total, mr.foreign_20d_total, mr.return_5d_avg, mr.return_20d_avg, mr.avg_change_pct, mr.whale_count, mr.total_value_triliun, CASE  WHEN (((mr.market_regime = 'BULL_STRONG') AND mr.regime_changed_today)) THEN ('REGIME_UPGRADE_BUY') WHEN (((mr.market_regime IN ('BULL_STRONG', 'BULL_MODERATE')) AND (mr.foreign_stance IN ('HEAVY_INFLOW', 'INFLOW')))) THEN ('ACCUMULATE') WHEN ((mr.market_regime = 'SIDEWAYS')) THEN ('SELECTIVE') WHEN (((mr.market_regime = 'BEAR_MODERATE') AND mr.regime_changed_today)) THEN ('REGIME_DOWNGRADE_REDUCE') WHEN ((mr.market_regime = 'BEAR_STRONG')) THEN ('DEFENSIVE') ELSE 'HOLD' END AS market_timing_signal, ((mr.breadth_score >= 55) AND (mr.foreign_today > 0)) AS is_accumulation_day, ((mr.breadth_score <= 35) AND (mr.foreign_today < 0)) AS is_risk_off_day FROM market.vw_s_market_regime AS mr;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_market_regime
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_market_regime AS WITH rolling AS (SELECT trading_date, breadth_score, adv_decline_ratio, net_foreign_miliar, avg_change_pct, whale_count, total_value_triliun, avg(breadth_score) OVER (ORDER BY trading_date ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS breadth_5d, avg(adv_decline_ratio) OVER (ORDER BY trading_date ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS adr_5d, sum(net_foreign_miliar) OVER (ORDER BY trading_date ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS foreign_5d_total, avg(avg_change_pct) OVER (ORDER BY trading_date ROWS BETWEEN 4 PRECEDING AND CURRENT ROW) AS return_5d_avg, avg(breadth_score) OVER (ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS breadth_20d, sum(net_foreign_miliar) OVER (ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS foreign_20d_total, avg(avg_change_pct) OVER (ORDER BY trading_date ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) AS return_20d_avg FROM market.vw_f_market_breadth)SELECT trading_date, breadth_score, breadth_5d, breadth_20d, foreign_5d_total, foreign_20d_total, return_5d_avg, return_20d_avg, net_foreign_miliar AS foreign_today, avg_change_pct, whale_count, total_value_triliun, CASE  WHEN (((breadth_5d >= 65) AND (foreign_5d_total > 0) AND (return_5d_avg > 0))) THEN ('BULL_STRONG') WHEN (((breadth_5d >= 50) AND (return_5d_avg > 0))) THEN ('BULL_MODERATE') WHEN ((breadth_5d >= 40)) THEN ('SIDEWAYS') WHEN (((breadth_5d < 30) AND (foreign_5d_total < 0) AND (return_5d_avg < 0))) THEN ('BEAR_STRONG') ELSE 'BEAR_MODERATE' END AS market_regime, CASE  WHEN ((foreign_5d_total > 500)) THEN ('HEAVY_INFLOW') WHEN ((foreign_5d_total > 100)) THEN ('INFLOW') WHEN ((foreign_5d_total > 0)) THEN ('MILD_INFLOW') WHEN ((foreign_5d_total > -100)) THEN ('MILD_OUTFLOW') WHEN ((foreign_5d_total > -500)) THEN ('OUTFLOW') ELSE 'HEAVY_OUTFLOW' END AS foreign_stance, CASE  WHEN (((breadth_score >= 65) AND (breadth_5d < 50))) THEN (CAST('t' AS BOOLEAN)) WHEN (((breadth_score < 40) AND (breadth_5d >= 50))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS regime_changed_today FROM rolling;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_price_momentum
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_price_momentum AS WITH market_daily AS (SELECT trading_date, avg(change_percent) AS mkt_avg_chg FROM market.daily_transactions GROUP BY trading_date)SELECT ph.stock_code, ph.trading_date, ph."close", ph.change_percent, ph.return_1d, ph.return_5d, ph.return_20d, ph.return_60d, ph.pct_from_52w_high, ph.pct_from_52w_low, round((ph.change_percent - m.mkt_avg_chg), 3) AS rs_vs_market_1d, round((ph.return_5d - avg(ph.return_5d) OVER (PARTITION BY ph.trading_date)), 3) AS rs_vs_market_5d, round((ph.return_20d - avg(ph.return_20d) OVER (PARTITION BY ph.trading_date)), 3) AS rs_vs_market_20d, CASE  WHEN ((ph.return_5d > (ph.return_20d + 2.0))) THEN ('ACCELERATING') WHEN ((ph.return_5d > ph.return_20d)) THEN ('BUILDING') WHEN ((ph.return_5d < (ph.return_20d - 2.0))) THEN ('DECELERATING') WHEN ((ph.return_5d < ph.return_20d)) THEN ('FADING') ELSE 'STABLE' END AS momentum_direction, CASE  WHEN (((ph.return_20d > 10) AND (ph.return_5d > 2))) THEN ('STRONG_UPTREND') WHEN (((ph.return_20d > 5) AND (ph.return_5d > 0))) THEN ('UPTREND') WHEN (((ph.return_20d < -10) AND (ph.return_5d < -2))) THEN ('STRONG_DOWNTREND') WHEN (((ph.return_20d < -5) AND (ph.return_5d < 0))) THEN ('DOWNTREND') WHEN ((abs(ph.return_20d) <= 5)) THEN ('SIDEWAYS') ELSE 'MIXED' END AS price_regime, (ph.pct_from_52w_high >= -3.0) AS near_52w_high, ((ph.return_20d < -5.0) AND (ph.return_60d > 0)) AS dip_in_uptrend, ph.sector, ph.group_name FROM market.vw_f_price_history AS ph INNER JOIN market_daily AS m ON ((ph.trading_date = m.trading_date));

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_price_vs_vwma
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_price_vs_vwma AS WITH base AS (SELECT stock_code, trading_date, "close", vwma_20d, change_percent, ("close" >= vwma_20d) AS above_vwma, round(((("close" - vwma_20d) / "nullif"(vwma_20d, 0)) * 100), 2) AS pct_from_vwma FROM market.daily_transactions WHERE (vwma_20d > 0)), with_flip AS (SELECT *, (above_vwma IS DISTINCT FROM lag(above_vwma) OVER (PARTITION BY stock_code ORDER BY trading_date)) AS flipped FROM base), with_group AS (SELECT *, sum(CASE  WHEN (flipped) THEN (1) ELSE 0 END) OVER (PARTITION BY stock_code ORDER BY trading_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS streak_group FROM with_flip)SELECT stock_code, trading_date, "close", vwma_20d, above_vwma, pct_from_vwma, (row_number() OVER (PARTITION BY stock_code, streak_group ORDER BY trading_date) * CASE  WHEN (above_vwma) THEN (1) ELSE -1 END) AS vwma_streak, CASE  WHEN ((above_vwma AND (pct_from_vwma >= 5.0))) THEN ('STRONG_ABOVE') WHEN ((above_vwma AND (pct_from_vwma >= 2.0))) THEN ('ABOVE') WHEN (above_vwma) THEN ('JUST_ABOVE') WHEN ((pct_from_vwma <= -5.0)) THEN ('STRONG_BELOW') WHEN ((pct_from_vwma <= -2.0)) THEN ('BELOW') ELSE 'JUST_BELOW' END AS vwma_signal, change_percent FROM with_group;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_prime_broker_flow
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_prime_broker_flow AS WITH prime_roll AS (SELECT stock_code, round((sum(CASE  WHEN (is_prime_foreign) THEN (net_value) ELSE 0 END) / 1000000000.0), 3) AS prime_net_total, round((sum(CASE  WHEN ((is_prime_foreign AND (date = (SELECT max(date) FROM main.broker_activity)))) THEN (net_value) ELSE 0 END) / 1000000000.0), 3) AS prime_net_1d, round((sum(CASE  WHEN ((is_prime_foreign AND (date >= ((SELECT max(date) FROM main.broker_activity) - CAST('4 days' AS INTERVAL))))) THEN (net_value) ELSE 0 END) / 1000000000.0), 3) AS prime_net_5d, round((sum(CASE  WHEN ((is_prime_foreign AND (date >= ((SELECT max(date) FROM main.broker_activity) - CAST('19 days' AS INTERVAL))))) THEN (net_value) ELSE 0 END) / 1000000000.0), 3) AS prime_net_20d, count(DISTINCT CASE  WHEN ((is_prime_foreign AND (net_value > 0) AND (date >= ((SELECT max(date) FROM main.broker_activity) - CAST('4 days' AS INTERVAL))))) THEN (broker_code) ELSE NULL END) AS prime_buyers_5d, count(DISTINCT CASE  WHEN (is_prime_foreign) THEN (broker_code) ELSE NULL END) AS prime_brokers_active, round((sum(CASE  WHEN (((category = 'FOREIGN') AND (NOT is_prime) AND (date >= ((SELECT max(date) FROM main.broker_activity) - CAST('4 days' AS INTERVAL))))) THEN (net_value) ELSE 0 END) / 1000000000.0), 3) AS non_prime_net_5d FROM main.vw_f_broker_net_daily WHERE (date >= ((SELECT max(date) FROM main.broker_activity) - CAST('20 days' AS INTERVAL))) GROUP BY stock_code)SELECT *, (prime_net_5d > 0) AS prime_is_buyer_5d, (prime_net_20d > 0) AS prime_is_buyer_20d, CASE  WHEN (((prime_net_5d > 0) AND (non_prime_net_5d > 0))) THEN ('ALIGNED_BUY') WHEN (((prime_net_5d > 0) AND (non_prime_net_5d <= 0))) THEN ('PRIME_LEADING') WHEN (((prime_net_5d <= 0) AND (non_prime_net_5d > 0))) THEN ('PRIME_LAGGING') WHEN (((prime_net_5d < 0) AND (non_prime_net_5d < 0))) THEN ('ALIGNED_SELL') ELSE 'MIXED' END AS prime_lead_signal, CASE  WHEN ((prime_buyers_5d >= 4)) THEN ('HIGH') WHEN ((prime_buyers_5d >= 2)) THEN ('MEDIUM') WHEN ((prime_buyers_5d >= 1)) THEN ('LOW') ELSE 'NONE' END AS prime_conviction FROM prime_roll;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_sector_leadership
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_sector_leadership AS WITH mkt AS (SELECT trading_date, avg_change_pct AS mkt_chg FROM market.vw_f_market_breadth)SELECT sd.trading_date, sd.sector, sd.avg_change_pct, sd.net_foreign_miliar, sd.total_value_miliar, sd.momentum_score, sd.whale_count, sd.gainers, sd.losers, sd.stock_count, m.mkt_chg, round((sd.avg_change_pct - m.mkt_chg), 3) AS vs_market, CASE  WHEN ((((sd.avg_change_pct - m.mkt_chg) >= 1.5) AND (sd.net_foreign_miliar > 0))) THEN ('LEADER') WHEN (((sd.avg_change_pct - m.mkt_chg) >= 1.0)) THEN ('OUTPERFORMER') WHEN ((((sd.avg_change_pct - m.mkt_chg) <= -1.5) AND (sd.net_foreign_miliar < 0))) THEN ('LAGGARD') WHEN (((sd.avg_change_pct - m.mkt_chg) <= -1.0)) THEN ('UNDERPERFORMER') ELSE 'INLINE' END AS leadership_status, CASE  WHEN ((sd.net_foreign_miliar > 50)) THEN ('STRONG_INFLOW') WHEN ((sd.net_foreign_miliar > 0)) THEN ('INFLOW') WHEN ((sd.net_foreign_miliar < -50)) THEN ('STRONG_OUTFLOW') WHEN ((sd.net_foreign_miliar < 0)) THEN ('OUTFLOW') ELSE 'NEUTRAL' END AS foreign_direction, sd.top_stock_by_value AS top_stock FROM market.vw_f_sector_daily AS sd INNER JOIN mkt AS m ON ((sd.trading_date = m.trading_date));

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_stealth_accumulation
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_stealth_accumulation AS WITH latest AS (SELECT max(trading_date) AS d FROM market.daily_transactions), lens_a_intraday AS (SELECT stock_code, count_star() FILTER (WHERE stealth_flag) AS intraday_stealth_days_20d, sum("value") FILTER (WHERE stealth_flag) AS intraday_stealth_value, max(aov_ratio_ma20) FILTER (WHERE stealth_flag) AS intraday_max_aov, sum(net_foreign_value) FILTER (WHERE stealth_flag) AS intraday_stealth_foreign, count_star() FILTER (WHERE (stealth_flag AND (net_foreign_value > 0))) AS intraday_foreign_buy_days FROM market.vw_f_volume_profile WHERE (trading_date >= ((SELECT d FROM latest) - CAST('19 days' AS INTERVAL))) GROUP BY stock_code), lens_b_foreign AS (SELECT ff.stock_code, ff.net_foreign_20d_miliar AS sustained_foreign_20d_miliar, ff.foreign_buy_days_20d AS sustained_buy_days_20d, ph.return_20d AS sustained_price_20d FROM market.vw_f_foreign_flow_daily AS ff INNER JOIN market.vw_f_price_history AS ph ON (((ff.stock_code = ph.stock_code) AND (ff.trading_date = ph.trading_date))) WHERE ((ff.trading_date = (SELECT d FROM latest)) AND (ff.net_foreign_20d_miliar >= 5.0) AND (abs(ph.return_20d) <= 10.0) AND (ff.foreign_buy_days_20d >= 10))), lens_c_ksei AS (SELECT stock_code, smart_money_miliar AS ksei_smart_miliar, sm_2m_positive AS ksei_sm_2m_positive, sm_3m_positive AS ksei_sm_3m_positive, sm_3m_cumulative_miliar AS ksei_3m_cumulative FROM ksei.vw_f_ksei_rolling_trend WHERE ((snapshot_date = (SELECT max(snapshot_date) FROM ksei.vw_f_ksei_rolling_trend)) AND (smart_money_miliar > 0))), broker_data AS (SELECT stock_code, foreign_net_20d AS broker_foreign_20d, inst_net_20d AS broker_inst_20d, retail_net_20d AS broker_retail_20d FROM main.vw_f_broker_category_rolling), price_data AS (SELECT stock_code, "close", return_5d AS price_5d, return_20d AS price_20d, return_60d AS price_60d FROM market.vw_f_price_history WHERE (trading_date = (SELECT d FROM latest))), all_candidates AS ((SELECT stock_code FROM lens_a_intraday WHERE (intraday_stealth_days_20d >= 2)) UNION ((SELECT stock_code FROM lens_b_foreign) UNION (SELECT stock_code FROM lens_c_ksei))), combined AS (SELECT c.stock_code, COALESCE(a.intraday_stealth_days_20d, 0) AS intraday_stealth_days, round((COALESCE(a.intraday_stealth_value, 0) / 1000000000.0), 3) AS intraday_stealth_value_miliar, round((COALESCE(a.intraday_stealth_foreign, 0) / 1000000000.0), 3) AS intraday_foreign_miliar, COALESCE(a.intraday_foreign_buy_days, 0) AS intraday_foreign_buy_days, round(COALESCE(a.intraday_max_aov, 0), 2) AS intraday_max_aov, COALESCE(b.sustained_foreign_20d_miliar, 0) AS sustained_foreign_20d_miliar, COALESCE(b.sustained_buy_days_20d, 0) AS sustained_buy_days_20d, b.sustained_price_20d AS sustained_price_20d, round(COALESCE(k.ksei_smart_miliar, 0), 2) AS ksei_smart_miliar, COALESCE(k.ksei_sm_2m_positive, CAST('f' AS BOOLEAN)) AS ksei_sm_2m_positive, COALESCE(k.ksei_sm_3m_positive, CAST('f' AS BOOLEAN)) AS ksei_sm_3m_positive, round(COALESCE(k.ksei_3m_cumulative, 0), 2) AS ksei_3m_cumulative_miliar, COALESCE(bd.broker_foreign_20d, 0) AS broker_foreign_20d, COALESCE(bd.broker_inst_20d, 0) AS broker_inst_20d, COALESCE(bd.broker_retail_20d, 0) AS broker_retail_20d, pd."close", pd.price_5d, pd.price_20d, pd.price_60d, ((a.intraday_stealth_days_20d IS NOT NULL) AND (a.intraday_stealth_days_20d >= 2)) AS lens_a_active, (b.sustained_foreign_20d_miliar IS NOT NULL) AS lens_b_active, ((k.ksei_smart_miliar IS NOT NULL) AND (k.ksei_smart_miliar > 0)) AS lens_c_active FROM all_candidates AS c LEFT JOIN lens_a_intraday AS a ON ((c.stock_code = a.stock_code)) LEFT JOIN lens_b_foreign AS b ON ((c.stock_code = b.stock_code)) LEFT JOIN lens_c_ksei AS k ON ((c.stock_code = k.stock_code)) LEFT JOIN broker_data AS bd ON ((c.stock_code = bd.stock_code)) LEFT JOIN price_data AS pd ON ((c.stock_code = pd.stock_code)))SELECT stock_code, lens_a_active, lens_b_active, lens_c_active, ((CAST(lens_a_active AS INTEGER) + CAST(lens_b_active AS INTEGER)) + CAST(lens_c_active AS INTEGER)) AS lens_count, intraday_stealth_days, intraday_stealth_value_miliar, intraday_foreign_miliar, intraday_foreign_buy_days, intraday_max_aov, sustained_foreign_20d_miliar, sustained_buy_days_20d, sustained_price_20d, ksei_smart_miliar, ksei_sm_2m_positive, ksei_sm_3m_positive, ksei_3m_cumulative_miliar, broker_foreign_20d, broker_inst_20d, broker_retail_20d, "close", price_5d, price_20d, price_60d, (((CASE  WHEN ((intraday_stealth_days >= 5)) THEN (4) WHEN ((intraday_stealth_days >= 3)) THEN (3) WHEN ((intraday_stealth_days >= 2)) THEN (2) ELSE 0 END + CASE  WHEN ((sustained_foreign_20d_miliar >= 50)) THEN (5) WHEN ((sustained_foreign_20d_miliar >= 20)) THEN (4) WHEN ((sustained_foreign_20d_miliar >= 10)) THEN (3) WHEN ((sustained_foreign_20d_miliar >= 5)) THEN (2) ELSE 0 END) + CASE  WHEN ((ksei_sm_3m_positive AND (ksei_smart_miliar >= 100))) THEN (4) WHEN ((ksei_sm_2m_positive AND (ksei_smart_miliar >= 50))) THEN (3) WHEN ((ksei_smart_miliar >= 100)) THEN (3) WHEN ((ksei_smart_miliar >= 20)) THEN (2) WHEN ((ksei_smart_miliar > 0)) THEN (1) ELSE 0 END) + CASE  WHEN ((broker_foreign_20d > 50)) THEN (2) WHEN ((broker_foreign_20d > 10)) THEN (1) ELSE 0 END) AS stealth_score, CASE  WHEN ((lens_a_active AND lens_b_active AND lens_c_active AND (abs(price_20d) <= 10))) THEN ('CONFIRMED_TRIPLE') WHEN ((lens_c_active AND (lens_a_active OR lens_b_active) AND (abs(price_20d) <= 12))) THEN ('HIGH') WHEN ((lens_b_active AND (sustained_foreign_20d_miliar >= 20) AND (broker_foreign_20d > 0))) THEN ('STRONG') WHEN (((lens_a_active AND (intraday_stealth_days >= 3)) OR (lens_b_active AND (sustained_foreign_20d_miliar >= 10)) OR (lens_c_active AND ksei_sm_2m_positive))) THEN ('MODERATE') ELSE 'WATCH' END AS stealth_quality, CASE  WHEN ((lens_a_active AND lens_b_active)) THEN ('INTRADAY_AND_SUSTAINED') WHEN (lens_a_active) THEN ('INTRADAY_ONLY') WHEN ((lens_b_active AND lens_c_active)) THEN ('SUSTAINED_KSEI') WHEN (lens_b_active) THEN ('SUSTAINED_ONLY') WHEN (lens_c_active) THEN ('KSEI_ONLY') ELSE 'WEAK' END AS stealth_type FROM combined;

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_volume_spike
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_volume_spike AS SELECT vp.stock_code, vp.trading_date, vp.volume, vp."value", vp.vol_ratio_ma20, vp.vol_tier, vp.aov_ratio_ma20, vp.aov_tier, vp.clean_whale_signal, vp.dual_spike_flag, CASE  WHEN ((vp.change_percent > 2.0)) THEN ('UP') WHEN ((vp.change_percent < -2.0)) THEN ('DOWN') ELSE 'FLAT' END AS price_direction, (vp.net_foreign_value > 0) AS foreign_confirmed, round((vp.net_foreign_value / 1000000000.0), 3) AS net_foreign_miliar, CASE  WHEN ((NOT vp.meets_value_threshold)) THEN ('NOISE') WHEN (((vp.vol_ratio_ma20 >= 3.0) AND (vp.net_foreign_value > 0) AND (vp.change_percent > 0))) THEN ('BREAKOUT_BULLISH') WHEN (((vp.vol_ratio_ma20 >= 3.0) AND (vp.change_percent < -2.0))) THEN ('BREAKDOWN_BEARISH') WHEN (((vp.vol_ratio_ma20 >= 2.0) AND vp.clean_whale_signal)) THEN ('INSTITUTIONAL_SPIKE') WHEN (((vp.vol_ratio_ma20 >= 1.5) AND (vp.change_percent > 0))) THEN ('HIGH_VOL_UP') WHEN (((vp.vol_ratio_ma20 >= 1.5) AND (vp.change_percent < 0))) THEN ('HIGH_VOL_DOWN') WHEN ((vp.vol_ratio_ma20 >= 1.5)) THEN ('HIGH_VOL_FLAT') ELSE 'NORMAL' END AS spike_type, vp.change_percent, vp."close" FROM market.vw_f_volume_profile AS vp WHERE ((vp.vol_ratio_ma20 >= 1.5) OR vp.clean_whale_signal);

-- ─────────────────────────────────────────────────────────────
-- market.vw_s_whale_timing
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_s_whale_timing AS SELECT ao.stock_code, ao.trading_date, ao."close", ao.change_percent, ao.volume, ao."value", ao.lot_per_tx, ao.aov_ratio_ma20, ao.aov_tier, ao.clean_whale_signal, ao.clean_big_player_anomaly, ao.stealth_flag, ao.distribution_flag, ao.net_foreign_miliar, ao.aov_signal, ao.stealth_days_20d, ao.whale_days_5d, least(10, (((CASE  WHEN (ao.clean_whale_signal) THEN (3) ELSE 0 END + CASE  WHEN (ao.clean_big_player_anomaly) THEN (3) ELSE 0 END) + CASE  WHEN ((ao.net_foreign_miliar > 0)) THEN (2) ELSE 0 END) + CASE  WHEN (ao.stealth_flag) THEN (2) ELSE 0 END)) AS whale_quality_score, CASE  WHEN ((ao.clean_whale_signal AND (ao.net_foreign_miliar > 0) AND ao.stealth_flag)) THEN ('FOREIGN_STEALTH_CONFIRMED') WHEN ((ao.clean_big_player_anomaly AND (ao.net_foreign_miliar > 0))) THEN ('PRIME_INSTITUTIONAL') WHEN ((ao.clean_whale_signal AND ao.stealth_flag)) THEN ('STEALTH_ACCUMULATION') WHEN ((ao.clean_whale_signal AND ao.distribution_flag)) THEN ('DISTRIBUTION') WHEN (ao.clean_whale_signal) THEN ('WHALE_UNCONFIRMED') ELSE 'NO_WHALE' END AS whale_verdict FROM market.vw_s_aov_anomaly AS ao WHERE (ao.clean_whale_signal OR ao.clean_big_player_anomaly OR (ao.stealth_days_20d >= 3));

-- ─────────────────────────────────────────────────────────────
-- market.vw_screener_allinone
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_screener_allinone AS SELECT sm.stock_code, COALESCE(sm.sector, 'Others') AS sector, sm."close", sm.change_percent, round(((COALESCE(v2.v2_score, 0) / 73.0) * 100), 0) AS smart_money_score, sm.whale_signal, sm.big_player_anomaly, sm.signal, COALESCE(v2.v2_score, 0) AS v2_score, v2.tier_v2, v2.flow_context, v2.aov_pts, v2.vwma_pts, v2.whale_pts, v2.foreign_pts, sm.smart_money_score AS smart_money_score_legacy, sp.aov_max_1d, sp.aov_max_7d, sp.aov_max_14d, sp.aov_max_30d, sp.aov_max_90d, sp.spike_1d, sp.spike_7d, sp.spike_14d, sp.spike_30d, sp.spike_90d, sp.foreign_1d, sp.foreign_7d, sp.foreign_14d, sp.foreign_30d, sp.foreign_90d FROM market.vw_smart_money_score AS sm LEFT JOIN market.screener_period AS sp ON ((sm.stock_code = sp.stock_code)) LEFT JOIN market.tb_composite_v2 AS v2 ON ((sm.stock_code = v2.stock_code)) ORDER BY smart_money_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_sector_analytics
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_sector_analytics AS WITH latest_date AS (SELECT max(trading_date) AS max_date FROM market.daily_transactions), daily_sector AS (SELECT d.trading_date, cp.sector, d.stock_code, d."close", d.change_percent, d.volume, d."value", d.net_foreign_value, d.aov_ratio_ma20, d.whale_signal, d.big_player_anomaly, d.vwma_20d, d.ma20_volume FROM market.daily_transactions AS d LEFT JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)) WHERE ((cp.sector IS NOT NULL) AND (d.trading_date >= ((SELECT max_date FROM latest_date) - CAST('30 days' AS INTERVAL))))), sector_agg AS (SELECT sector, count(DISTINCT stock_code) AS stock_count, avg(CASE  WHEN ((trading_date = (SELECT max_date FROM latest_date))) THEN (change_percent) ELSE NULL END) AS avg_change_pct, sum(CASE  WHEN ((trading_date = (SELECT max_date FROM latest_date))) THEN ("value") ELSE NULL END) AS total_value, sum(CASE  WHEN ((trading_date = (SELECT max_date FROM latest_date))) THEN (volume) ELSE NULL END) AS total_volume, sum(CASE  WHEN ((trading_date = (SELECT max_date FROM latest_date))) THEN (net_foreign_value) ELSE NULL END) AS foreign_flow, avg(CASE  WHEN ((trading_date = (SELECT max_date FROM latest_date))) THEN (aov_ratio_ma20) ELSE NULL END) AS avg_aov, max(CASE  WHEN ((trading_date = (SELECT max_date FROM latest_date))) THEN (aov_ratio_ma20) ELSE NULL END) AS max_aov, count(CASE  WHEN (((trading_date = (SELECT max_date FROM latest_date)) AND (aov_ratio_ma20 >= 1.5))) THEN (1) ELSE NULL END) AS aov_spike_count, count(CASE  WHEN (((trading_date = (SELECT max_date FROM latest_date)) AND whale_signal)) THEN (1) ELSE NULL END) AS whale_count, count(CASE  WHEN (((trading_date = (SELECT max_date FROM latest_date)) AND big_player_anomaly)) THEN (1) ELSE NULL END) AS anomaly_count, count(CASE  WHEN (((trading_date = (SELECT max_date FROM latest_date)) AND ("close" >= vwma_20d))) THEN (1) ELSE NULL END) AS above_vwma_count, count(CASE  WHEN (((trading_date = (SELECT max_date FROM latest_date)) AND (volume > (ma20_volume * 1.5)))) THEN (1) ELSE NULL END) AS volume_spike_count, count(CASE  WHEN (((trading_date = (SELECT max_date FROM latest_date)) AND (change_percent > 0))) THEN (1) ELSE NULL END) AS gainers, count(CASE  WHEN (((trading_date = (SELECT max_date FROM latest_date)) AND (change_percent < 0))) THEN (1) ELSE NULL END) AS losers, sum(net_foreign_value) AS foreign_30d, avg(change_percent) AS avg_change_30d, sum("value") AS total_value_30d, count(CASE  WHEN ((aov_ratio_ma20 >= 1.5)) THEN (1) ELSE NULL END) AS aov_spike_30d, count(CASE  WHEN (whale_signal) THEN (1) ELSE NULL END) AS whale_30d, "first"(stock_code ORDER BY "value" DESC) AS top_stock_code, "first"("close" ORDER BY "value" DESC) AS top_stock_price, "first"(change_percent ORDER BY "value" DESC) AS top_stock_change FROM daily_sector GROUP BY sector)SELECT *, least(100, greatest(0, ((((((CASE  WHEN ((avg_change_pct > 0)) THEN (20) ELSE -10 END + CASE  WHEN ((foreign_flow > 0)) THEN (20) ELSE -10 END) + CASE  WHEN ((aov_spike_count > (stock_count * 0.1))) THEN (15) ELSE 0 END) + CASE  WHEN ((whale_count > 0)) THEN (10) ELSE 0 END) + CASE  WHEN ((gainers > losers)) THEN (15) ELSE 0 END) + CASE  WHEN ((volume_spike_count > (stock_count * 0.1))) THEN (10) ELSE 0 END) + CASE  WHEN ((above_vwma_count > (stock_count * 0.5))) THEN (10) ELSE 0 END))) AS momentum_score, CASE  WHEN ((momentum_score >= 70)) THEN ('🚀 STRONG BULLISH') WHEN ((momentum_score >= 50)) THEN ('📈 BULLISH') WHEN ((momentum_score >= 30)) THEN ('➖ NEUTRAL') WHEN ((momentum_score >= 10)) THEN ('📉 BEARISH') ELSE '🔻 STRONG BEARISH' END AS signal, CASE  WHEN ((abs(foreign_flow) > 500000000000)) THEN ('🔥 VERY HIGH') WHEN ((abs(foreign_flow) > 100000000000)) THEN ('📊 HIGH') WHEN ((abs(foreign_flow) > 10000000000)) THEN ('📉 MODERATE') ELSE '💤 LOW' END AS flow_intensity FROM sector_agg ORDER BY momentum_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_smart_money_score
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_smart_money_score AS WITH latest_daily AS (SELECT stock_code, "close", change_percent, net_foreign_value, whale_signal, big_player_anomaly, aov_ratio_ma20 FROM market.daily_transactions WHERE (trading_date = (SELECT max(trading_date) FROM market.daily_transactions))), foreign_30d AS (SELECT stock_code, sum(net_foreign_value) AS foreign_30d FROM market.daily_transactions WHERE (trading_date >= ((SELECT max(trading_date) FROM market.daily_transactions) - CAST('30 days' AS INTERVAL))) GROUP BY stock_code), broker_net AS (SELECT stock_code, sum("value") AS broker_net_value FROM main.broker_activity WHERE (date = (SELECT max(date) FROM main.broker_activity)) GROUP BY stock_code)SELECT d.stock_code, COALESCE(cp.sector, 'Others') AS sector, d."close", d.change_percent, COALESCE(f.foreign_30d, 0) AS foreign_30d, COALESCE(b.broker_net_value, 0) AS broker_net, d.whale_signal, d.big_player_anomaly, d.aov_ratio_ma20, least(100, ((((CASE  WHEN ((COALESCE(f.foreign_30d, 0) > 0)) THEN (25) ELSE 0 END + CASE  WHEN ((COALESCE(b.broker_net_value, 0) > 0)) THEN (20) ELSE 0 END) + CASE  WHEN (d.whale_signal) THEN (20) ELSE 0 END) + CASE  WHEN (d.big_player_anomaly) THEN (15) ELSE 0 END) + CASE  WHEN ((d.aov_ratio_ma20 >= 1.5)) THEN (20) ELSE 0 END)) AS smart_money_score, CASE  WHEN ((least(100, ((((CASE  WHEN ((COALESCE(f.foreign_30d, 0) > 0)) THEN (25) ELSE 0 END + CASE  WHEN ((COALESCE(b.broker_net_value, 0) > 0)) THEN (20) ELSE 0 END) + CASE  WHEN (d.whale_signal) THEN (20) ELSE 0 END) + CASE  WHEN (d.big_player_anomaly) THEN (15) ELSE 0 END) + CASE  WHEN ((d.aov_ratio_ma20 >= 1.5)) THEN (20) ELSE 0 END)) >= 70)) THEN ('🚀 STRONG BUY') WHEN ((least(100, ((((CASE  WHEN ((COALESCE(f.foreign_30d, 0) > 0)) THEN (25) ELSE 0 END + CASE  WHEN ((COALESCE(b.broker_net_value, 0) > 0)) THEN (20) ELSE 0 END) + CASE  WHEN (d.whale_signal) THEN (20) ELSE 0 END) + CASE  WHEN (d.big_player_anomaly) THEN (15) ELSE 0 END) + CASE  WHEN ((d.aov_ratio_ma20 >= 1.5)) THEN (20) ELSE 0 END)) >= 45)) THEN ('👀 WATCH') ELSE '➖ NEUTRAL' END AS signal FROM latest_daily AS d LEFT JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)) LEFT JOIN foreign_30d AS f ON ((d.stock_code = f.stock_code)) LEFT JOIN broker_net AS b ON ((d.stock_code = b.stock_code)) ORDER BY smart_money_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_stock_detail
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_stock_detail AS SELECT d.stock_code, d.trading_date, d.open_price, d.high, d.low, d."close", d.previous, d.change_percent, d.volume, d."value", d.frequency, d.net_foreign_value, d.foreign_buy_value, d.foreign_sell_value, d.vwma_20d, d.ma20_volume, d.aov_ratio_ma20, d.avg_order_volume, d.ma50_avg_order_volume, d.whale_signal, d.big_player_anomaly, d.signal, d.tradeable_shares, COALESCE(cp.sector, 'Others') AS sector, cp.free_float, COALESCE(cp.group_name, 'Others') AS group_name, cp.company_name FROM market.daily_transactions AS d LEFT JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code));

-- ─────────────────────────────────────────────────────────────
-- market.vw_stock_latest
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_stock_latest AS SELECT d.*, COALESCE(cp.sector, 'Others') AS sector, cp.free_float, COALESCE(cp.group_name, 'Others') AS group_name, cp.company_name, CASE  WHEN ((d.change_percent >= 4)) THEN ('🚀 STRONG UP') WHEN ((d.change_percent >= 1)) THEN ('📈 UP') WHEN ((d.change_percent <= -4)) THEN ('🔻 STRONG DOWN') WHEN ((d.change_percent <= -1)) THEN ('📉 DOWN') ELSE '➖ FLAT' END AS price_action FROM market.daily_transactions AS d LEFT JOIN market.company_profile AS cp ON ((d.stock_code = cp.stock_code)) WHERE (d.trading_date = (SELECT max(trading_date) FROM market.daily_transactions));

-- ─────────────────────────────────────────────────────────────
-- market.vw_stock_multi_signal
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_stock_multi_signal AS WITH ksei_latest AS (SELECT ms.Code AS stock_code, CASE  WHEN (g.Is_CorpAction_Suspect) THEN (0) ELSE round((((ms.Local_CP_Chg_Val + ms.Local_PF_Chg_Val) + ms.Local_IB_Chg_Val) / 1000000000.0), 3) END AS ksei_local_smart_miliar, CASE  WHEN (g.Is_CorpAction_Suspect) THEN (0) ELSE round((((ms.Foreign_CP_Chg_Val + ms.Foreign_PF_Chg_Val) + ms.Foreign_IB_Chg_Val) / 1000000000.0), 3) END AS ksei_foreign_smart_miliar, CASE  WHEN (g.Is_CorpAction_Suspect) THEN (0) ELSE round(((((ms.Local_CP_Chg_Val + ms.Local_PF_Chg_Val) + ms.Local_IB_Chg_Val) + ((ms.Foreign_CP_Chg_Val + ms.Foreign_PF_Chg_Val) + ms.Foreign_IB_Chg_Val)) / 1000000000.0), 3) END AS ksei_net_smart_miliar, round((ms.Local_ID_Chg_Val / 1000000000.0), 3) AS ksei_retail_miliar, ms.Is_Split_Suspect, ms.Is_Reverse_Suspect FROM ksei.monthly_snapshot AS ms LEFT JOIN ksei.vw_f_ksei_monthly_delta_v2 AS g ON (((g.stock_code = ms.Code) AND (g.snapshot_date = ms.Date))) WHERE (ms.Date = (SELECT max(Date) FROM ksei.monthly_snapshot)))SELECT sl.stock_code, sl.trading_date, sl."close", sl.change_percent, sl.vwma_20d, sl.aov_ratio_ma20, sl.whale_signal, sl.big_player_anomaly, sl.signal AS market_signal, sl.sector, sl.group_name, sl.free_float, COALESCE(br.foreign_broker_net_1d, 0) AS foreign_broker_net_1d, COALESCE(br.foreign_broker_net_7d, 0) AS foreign_broker_net_7d, COALESCE(br.foreign_broker_net_30d, 0) AS foreign_broker_net_30d, COALESCE(br.prime_broker_net_7d, 0) AS prime_broker_net_7d, COALESCE(br.local_inst_net_1d, 0) AS local_inst_net_1d, COALESCE(br.local_inst_net_7d, 0) AS local_inst_net_7d, COALESCE(br.local_inst_net_30d, 0) AS local_inst_net_30d, COALESCE(br.retail_net_1d, 0) AS retail_net_1d, COALESCE(br.retail_net_7d, 0) AS retail_net_7d, COALESCE(br.foreign_brokers_buying_7d, 0) AS foreign_brokers_buying_7d, COALESCE(br.local_inst_brokers_buying_7d, 0) AS local_inst_brokers_buying_7d, COALESCE(sp.foreign_1d, 0) AS foreign_net_1d, COALESCE(sp.foreign_7d, 0) AS foreign_net_7d, COALESCE(sp.foreign_30d, 0) AS foreign_net_30d, COALESCE(sp.foreign_90d, 0) AS foreign_net_90d, COALESCE(k.ksei_net_smart_miliar, 0) AS ksei_net_smart_miliar, COALESCE(k.ksei_local_smart_miliar, 0) AS ksei_local_smart_miliar, COALESCE(k.ksei_foreign_smart_miliar, 0) AS ksei_foreign_smart_miliar, COALESCE(k.ksei_retail_miliar, 0) AS ksei_retail_miliar, COALESCE(k.Is_Split_Suspect, CAST('f' AS BOOLEAN)) AS is_split_suspect, COALESCE(k.Is_Reverse_Suspect, CAST('f' AS BOOLEAN)) AS is_reverse_suspect, COALESCE(ic.conviction_score, 0) AS insider_conviction_score, ic.insider_signal, COALESCE(ic.fresh_internal_buy, CAST('f' AS BOOLEAN)) AS fresh_insider_buy, COALESCE(ic.fresh_internal_sell, CAST('f' AS BOOLEAN)) AS fresh_insider_sell, CASE  WHEN ((sl.whale_signal AND (COALESCE(br.foreign_broker_net_7d, 0) > 0) AND (COALESCE(br.local_inst_net_7d, 0) > 0))) THEN ('⚡ TRIPLE CONFLUENCE') WHEN (((COALESCE(br.foreign_broker_net_7d, 0) > 0) AND (COALESCE(br.prime_broker_net_7d, 0) > 0))) THEN ('🟢 PRIME FOREIGN BUY') WHEN ((sl.whale_signal AND (COALESCE(br.foreign_broker_net_7d, 0) > 0))) THEN ('🟢 WHALE + FOREIGN BROKER') WHEN (((COALESCE(k.ksei_net_smart_miliar, 0) > 0) AND (COALESCE(br.local_inst_net_7d, 0) > 0))) THEN ('🟢 KSEI + LOCAL INST') WHEN ((COALESCE(ic.fresh_internal_buy, CAST('f' AS BOOLEAN)) AND ((COALESCE(br.foreign_broker_net_7d, 0) > 0) OR (COALESCE(br.local_inst_net_7d, 0) > 0)))) THEN ('🟢 INSIDER + BROKER') WHEN (((COALESCE(br.retail_net_7d, 0) < 0) AND ((COALESCE(br.foreign_broker_net_7d, 0) > 0) OR (COALESCE(br.local_inst_net_7d, 0) > 0)))) THEN ('🟡 INST BUY / RETAIL SELL') WHEN ((sl.whale_signal OR (COALESCE(br.foreign_broker_net_7d, 0) > 0) OR (COALESCE(k.ksei_net_smart_miliar, 0) > 0))) THEN ('🟡 SINGLE SIGNAL') WHEN ((COALESCE(ic.fresh_internal_sell, CAST('f' AS BOOLEAN)) AND (COALESCE(br.foreign_broker_net_7d, 0) < 0))) THEN ('🔴 INSIDER + FOREIGN SELL') ELSE '⚪ NEUTRAL' END AS composite_signal FROM market.vw_stock_latest AS sl LEFT JOIN main.vw_broker_rolling_net AS br ON ((sl.stock_code = br.stock_code)) LEFT JOIN market.screener_period AS sp ON ((sl.stock_code = sp.stock_code)) LEFT JOIN ksei_latest AS k ON ((sl.stock_code = k.stock_code)) LEFT JOIN main.vw_insider_conviction_score AS ic ON ((sl.stock_code = ic.stock_code));

-- ─────────────────────────────────────────────────────────────
-- market.vw_stock_screener
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_stock_screener AS WITH ld AS (SELECT max(trading_date) AS max_date FROM market.daily_transactions), mp AS (SELECT dt.stock_code, CAST(sum(CASE  WHEN ((dt.trading_date >= (ld.max_date - CAST('1 day' AS INTERVAL)))) THEN (dt.net_foreign_value) ELSE 0 END) AS BIGINT) AS f1d, CAST(sum(CASE  WHEN ((dt.trading_date >= (ld.max_date - CAST('7 days' AS INTERVAL)))) THEN (dt.net_foreign_value) ELSE 0 END) AS BIGINT) AS f7d, CAST(sum(CASE  WHEN ((dt.trading_date >= (ld.max_date - CAST('14 days' AS INTERVAL)))) THEN (dt.net_foreign_value) ELSE 0 END) AS BIGINT) AS f14d, CAST(sum(CASE  WHEN ((dt.trading_date >= (ld.max_date - CAST('30 days' AS INTERVAL)))) THEN (dt.net_foreign_value) ELSE 0 END) AS BIGINT) AS f30d, CAST(sum(CASE  WHEN ((dt.trading_date >= (ld.max_date - CAST('60 days' AS INTERVAL)))) THEN (dt.net_foreign_value) ELSE 0 END) AS BIGINT) AS f60d, CAST(sum(CASE  WHEN ((dt.trading_date >= (ld.max_date - CAST('90 days' AS INTERVAL)))) THEN (dt.net_foreign_value) ELSE 0 END) AS BIGINT) AS f90d, CAST(sum(CASE  WHEN ((dt.trading_date >= (ld.max_date - CAST('120 days' AS INTERVAL)))) THEN (dt.net_foreign_value) ELSE 0 END) AS BIGINT) AS f120d FROM market.daily_transactions AS dt , ld WHERE (dt.trading_date >= (ld.max_date - CAST('120 days' AS INTERVAL))) GROUP BY dt.stock_code)SELECT sms.stock_code, sms.sector, cp.group_name, sms."close", sms.change_percent, dl."value", sms.whale_signal, sms.big_player_anomaly, sms.smart_money_score, sms.broker_net, sms.signal, COALESCE(mp.f1d, 0) AS f1d, COALESCE(mp.f7d, 0) AS f7d, COALESCE(mp.f14d, 0) AS f14d, COALESCE(mp.f30d, 0) AS f30d, COALESCE(mp.f60d, 0) AS f60d, COALESCE(mp.f90d, 0) AS f90d, COALESCE(mp.f120d, 0) AS f120d FROM market.vw_smart_money_score AS sms LEFT JOIN market.company_profile AS cp ON ((cp.stock_code = sms.stock_code)) LEFT JOIN mp ON ((mp.stock_code = sms.stock_code)) LEFT JOIN market.vw_stock_latest AS dl ON ((dl.stock_code = sms.stock_code));

-- ─────────────────────────────────────────────────────────────
-- market.vw_tactical_momentum_smart_money
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_tactical_momentum_smart_money AS WITH max_dt AS (SELECT max(trading_date) AS d FROM market.daily_transactions), broker_ranked AS (SELECT "left"(ba.stock_code, 4) AS stock_code, ba."value", dense_rank() OVER (ORDER BY ba.date DESC) AS dr FROM main.broker_activity AS ba INNER JOIN main.broker_classification AS bc ON ((bc.broker_code = ba.broker_code)) WHERE ((ba.date >= ((SELECT d FROM max_dt) - CAST('60 days' AS INTERVAL))) AND (upper(bc.category) IN ('FOREIGN', 'LOCAL_INST')))), broker_roll AS (SELECT stock_code, round((sum(CASE  WHEN ((dr <= 7)) THEN ("value") ELSE 0 END) / 1000000000.0), 3) AS broker_net_7d_miliar, round((sum(CASE  WHEN ((dr <= 30)) THEN ("value") ELSE 0 END) / 1000000000.0), 3) AS broker_net_30d_miliar FROM broker_ranked GROUP BY stock_code), foreign_ranked AS (SELECT stock_code, net_foreign_value, row_number() OVER (PARTITION BY stock_code ORDER BY trading_date DESC) AS rn FROM market.daily_transactions WHERE (trading_date >= ((SELECT d FROM max_dt) - CAST('60 days' AS INTERVAL)))), foreign_roll AS (SELECT stock_code, sum(CASE  WHEN ((rn = 1)) THEN (net_foreign_value) ELSE 0 END) AS net_foreign_1d, round((sum(CASE  WHEN ((rn <= 7)) THEN (net_foreign_value) ELSE 0 END) / 1000000000.0), 3) AS net_foreign_7d_miliar, round((sum(CASE  WHEN ((rn <= 30)) THEN (net_foreign_value) ELSE 0 END) / 1000000000.0), 3) AS net_foreign_30d_miliar FROM foreign_ranked GROUP BY stock_code)SELECT d.stock_code, d.trading_date, d."close", d.change_percent, d.volume, COALESCE(f.net_foreign_1d, 0) AS net_foreign_1d, COALESCE(f.net_foreign_7d_miliar, 0) AS net_foreign_7d_miliar, COALESCE(f.net_foreign_30d_miliar, 0) AS net_foreign_30d_miliar, COALESCE(b.broker_net_7d_miliar, 0) AS broker_net_7d_miliar, COALESCE(b.broker_net_30d_miliar, 0) AS broker_net_30d_miliar, CASE  WHEN (((COALESCE(f.net_foreign_7d_miliar, 0) > 50) AND (COALESCE(b.broker_net_7d_miliar, 0) > 50))) THEN ('🟢 Strong Buy') WHEN (((COALESCE(f.net_foreign_7d_miliar, 0) > 10) AND (COALESCE(b.broker_net_7d_miliar, 0) > 10))) THEN ('🟡 Moderate Buy') WHEN (((COALESCE(f.net_foreign_7d_miliar, 0) > 0) AND (COALESCE(b.broker_net_7d_miliar, 0) > 0))) THEN ('🔵 Mild Buy') WHEN (((COALESCE(f.net_foreign_7d_miliar, 0) < -50) AND (COALESCE(b.broker_net_7d_miliar, 0) < -50))) THEN ('🔴 Strong Sell') WHEN (((COALESCE(f.net_foreign_7d_miliar, 0) < -10) AND (COALESCE(b.broker_net_7d_miliar, 0) < -10))) THEN ('🟠 Moderate Sell') WHEN (((COALESCE(f.net_foreign_7d_miliar, 0) > 0) AND (COALESCE(b.broker_net_7d_miliar, 0) < 0))) THEN ('⚡ Foreign Buy / Broker Sell') WHEN (((COALESCE(f.net_foreign_7d_miliar, 0) < 0) AND (COALESCE(b.broker_net_7d_miliar, 0) > 0))) THEN ('⚡ Broker Buy / Foreign Sell') ELSE '⚪ Neutral' END AS tactical_signal FROM market.daily_transactions AS d LEFT JOIN broker_roll AS b ON ((d.stock_code = b.stock_code)) LEFT JOIN foreign_roll AS f ON ((d.stock_code = f.stock_code)) WHERE ((d.trading_date = (SELECT d FROM max_dt)) AND (d."value" > 1000000000));

-- ─────────────────────────────────────────────────────────────
-- market.vw_volume_spike
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_volume_spike AS WITH latest_date AS (SELECT CAST(max(trading_date) AS DATE) AS max_date FROM market.daily_transactions)SELECT d.stock_code, d.trading_date, d."close", d.volume, d.ma20_volume, round((CAST(d.volume AS DOUBLE) / "nullif"(d.ma20_volume, 0)), 2) AS volume_ratio, d.change_percent, d.net_foreign_value, d.whale_signal, CASE  WHEN ((((CAST(d.volume AS DOUBLE) / "nullif"(d.ma20_volume, 0)) >= 2.0) AND (d.change_percent > 0) AND (d.net_foreign_value > 0))) THEN ('🚀 BREAKOUT BULLISH') WHEN ((((CAST(d.volume AS DOUBLE) / "nullif"(d.ma20_volume, 0)) >= 2.0) AND (d.change_percent < 0))) THEN ('🔻 BREAKDOWN BEARISH') WHEN ((((CAST(d.volume AS DOUBLE) / "nullif"(d.ma20_volume, 0)) >= 1.5) AND (d.change_percent > 0))) THEN ('📈 HIGH VOL UP') WHEN ((((CAST(d.volume AS DOUBLE) / "nullif"(d.ma20_volume, 0)) >= 1.5) AND (d.change_percent < 0))) THEN ('📉 HIGH VOL DOWN') ELSE 'NORMAL' END AS spike_type FROM market.daily_transactions AS d , latest_date AS l WHERE ((CAST(d.trading_date AS DATE) >= (l.max_date - CAST('30 days' AS INTERVAL))) AND (d.ma20_volume > 0)) ORDER BY volume_ratio DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_watchlist_radar
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_watchlist_radar AS SELECT ms.stock_code, ms.sector, ms.group_name, ms."close", ms.change_percent, ms.market_signal, ms.composite_signal, ms.foreign_broker_net_7d, ms.local_inst_net_7d, ms.retail_net_7d, ms.prime_broker_net_7d, ms.foreign_net_7d, ms.foreign_net_30d, ms.ksei_net_smart_miliar, ms.insider_conviction_score, ms.insider_signal, ms.fresh_insider_buy, ms.fresh_insider_sell, ms.whale_signal, ms.big_player_anomaly, ms.aov_ratio_ma20, ms.is_split_suspect, ms.is_reverse_suspect, least(100, greatest(0, (((((((CASE  WHEN ((ms.change_percent > 2)) THEN (15) WHEN ((ms.change_percent > 0)) THEN (8) ELSE 0 END + CASE  WHEN ((ms.foreign_broker_net_7d > 20)) THEN (20) WHEN ((ms.foreign_broker_net_7d > 5)) THEN (13) WHEN ((ms.foreign_broker_net_7d > 0)) THEN (7) ELSE 0 END) + CASE  WHEN ((ms.local_inst_net_7d > 20)) THEN (15) WHEN ((ms.local_inst_net_7d > 5)) THEN (10) WHEN ((ms.local_inst_net_7d > 0)) THEN (5) ELSE 0 END) + CASE  WHEN ((ms.retail_net_7d < -5)) THEN (5) WHEN ((ms.retail_net_7d < 0)) THEN (2) ELSE 0 END) + CASE  WHEN ((ms.ksei_net_smart_miliar > 100)) THEN (20) WHEN ((ms.ksei_net_smart_miliar > 10)) THEN (12) WHEN ((ms.ksei_net_smart_miliar > 0)) THEN (6) ELSE 0 END) + CASE  WHEN (ms.whale_signal) THEN (10) ELSE 0 END) + CASE  WHEN ((ms.aov_ratio_ma20 >= 2.0)) THEN (5) WHEN ((ms.aov_ratio_ma20 >= 1.5)) THEN (3) ELSE 0 END) + CASE  WHEN ((ms.fresh_insider_buy AND (ms.insider_conviction_score >= 15))) THEN (10) WHEN (ms.fresh_insider_buy) THEN (6) ELSE 0 END))) AS radar_score, CASE  WHEN (ms.is_split_suspect) THEN ('⚠️ SPLIT SUSPECT') WHEN (ms.is_reverse_suspect) THEN ('⚠️ REVERSE SPLIT SUSPECT') ELSE NULL END AS warning_flag FROM market.vw_stock_multi_signal AS ms WHERE (ms."close" > 0) ORDER BY radar_score DESC;

-- ─────────────────────────────────────────────────────────────
-- market.vw_whale_activity
-- ─────────────────────────────────────────────────────────────
CREATE VIEW market.vw_whale_activity AS WITH latest_date AS (SELECT CAST(max(trading_date) AS DATE) AS max_date FROM market.daily_transactions)SELECT d.stock_code, count_star() AS total_days, count(CASE  WHEN (d.whale_signal) THEN (1) ELSE NULL END) AS whale_days, count(CASE  WHEN (d.big_player_anomaly) THEN (1) ELSE NULL END) AS anomaly_days, round(((CAST(count(CASE  WHEN (d.whale_signal) THEN (1) ELSE NULL END) AS DOUBLE) / "nullif"(count_star(), 0)) * 100), 2) AS whale_pct, sum(d.net_foreign_value) AS total_foreign, round(avg(d."close"), 2) AS avg_price, round(avg(d.aov_ratio_ma20), 2) AS avg_aov_ratio FROM market.daily_transactions AS d , latest_date AS l WHERE (CAST(d.trading_date AS DATE) >= (l.max_date - CAST('60 days' AS INTERVAL))) GROUP BY d.stock_code HAVING (count(CASE  WHEN (d.whale_signal) THEN (1) ELSE NULL END) >= 3) ORDER BY whale_days DESC;
